// Ladin Ormanı — 4. sınıf Türkçe: test tarzı (sosyal4.js düzeni). Her hafta ÖZGÜN bir okuma metni + metne dayalı sorular
// + dil bilgisi bankalarından hesaplanan sorular (eş/zıt anlam, deyim, atasözü, noktalama). İki sayfa + ayrı cevap anahtarı.
// Metin soruları: [kök, doğru, [yanlış, yanlış, yanlış]]. Üretim: node kaynak/calisma-kagitlari/uret.js t4
module.exports = ({ T, S }) => {
  const { p, kodDY, yolDY, kapDY, roma, sirala, esle, kacTane, kareYol, cocukSec, ortak, sayfa, optik, yeniHafta, cevapSayfasi } = T;
  void S;
  const RNG = s => { let x = 0; for (const c of String(s)) x = (x * 31 + c.charCodeAt(0)) >>> 0; x = x || 1; return () => ((x = (x * 1103515245 + 12345) >>> 0) / 4294967296); };
  const kar = (r, l) => { const a = [...l]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const coktan = (ic, kok, d, y) => { const l = [d, ...y].map(x => String(x).replace(/<[^>]+>/g, '')); return T.soru(ic, kok, T.sec(d, y, kok), { kolon: l.every(x => x.length <= 6) ? 4 : l.every(x => x.length <= 20) ? 2 : 1 }); };
  const ADLAR = ['Elif', 'Kaan', 'Defne', 'Mert', 'Zeynep', 'Emir', 'Ada', 'Yusuf', 'Ecrin', 'Alp', 'Nehir', 'Ömer'];

  // ——— Dil bilgisi bankaları (doğruluk bankadan hesaplanır) ———
  const ES = [['cevap', 'yanıt'], ['öğrenci', 'talebe'], ['armağan', 'hediye'], ['yurt', 'vatan'], ['kırmızı', 'al'], ['siyah', 'kara'], ['ihtiyar', 'yaşlı'], ['misafir', 'konuk'], ['sınav', 'imtihan'], ['okul', 'mektep'], ['hekim', 'doktor'], ['kelime', 'sözcük'], ['istek', 'arzu'], ['yıl', 'sene']];
  const ZIT = [['uzun', 'kısa'], ['sıcak', 'soğuk'], ['geniş', 'dar'], ['erken', 'geç'], ['kolay', 'zor'], ['temiz', 'kirli'], ['cesur', 'korkak'], ['eski', 'yeni'], ['ağır', 'hafif'], ['derin', 'sığ'], ['çalışkan', 'tembel'], ['gece', 'gündüz'], ['iç', 'dış'], ['ileri', 'geri']];
  const DEYIM = [['kulak vermek', 'dikkatle dinlemek'], ['göz atmak', 'kısaca bakmak'], ['eli açık olmak', 'cömert olmak'], ['ağzı kulaklarına varmak', 'çok sevinmek'], ['kalbini kırmak', 'birini üzmek'], ['dili tutulmak', 'şaşırıp konuşamamak'], ['ayağını denk almak', 'dikkatli davranmak'], ['burnu havada olmak', 'kibirli olmak'], ['gözden düşmek', 'değerini yitirmek'], ['içi içine sığmamak', 'çok heyecanlanmak']];
  const ATA = [['Damlaya damlaya göl olur.', 'Küçük birikimler zamanla büyür.'], ['Bugünün işini yarına bırakma.', 'İşleri zamanında yapmalıyız.'], ['Bir elin nesi var, iki elin sesi var.', 'Birlikte çalışmak başarı getirir.'], ['Ağaç yaşken eğilir.', 'Eğitim küçük yaşta başlamalıdır.'], ['Sakla samanı, gelir zamanı.', 'Gereksiz görünen şey bir gün işe yarar.'], ['Komşu komşunun külüne muhtaçtır.', 'İnsanlar birbirine ihtiyaç duyar.']];
  const NOKTA = [['Ne güzel bir gün', '!'], ['Yarın okula gelecek misin', '?'], ['Kitabımı masaya koydum', '.'], ['Eyvah, süt taştı', '!'], ['Bu kitabı kim yazmış', '?'], ['Annem bahçede çiçek suluyor', '.']];
  const ISAD = { '!': 'ünlem', '?': 'soru işareti', '.': 'nokta' };
  const dilSt = r => { const e = kar(r, ES), z = kar(r, ZIT), d = kar(r, DEYIM), a = kar(r, ATA), n = kar(r, NOKTA); const f = (t, y) => r() < .5 ? [t, true] : [y, false];
    return [f(`“${e[0][0]}” ile “${e[0][1]}” eş anlamlı sözcüklerdir.`, `“${z[0][0]}” ile “${z[0][1]}” eş anlamlı sözcüklerdir.`),
      f(`“${z[1][0]}” ile “${z[1][1]}” zıt anlamlı sözcüklerdir.`, `“${e[1][0]}” ile “${e[1][1]}” zıt anlamlı sözcüklerdir.`),
      f(`“${d[0][0]}” deyimi “${d[0][1]}” anlamındadır.`, `“${d[0][0]}” deyimi “${d[1][1]}” anlamındadır.`),
      f(`“${a[0][0]}” atasözü “${a[0][1]}” anlamındadır.`, `“${a[0][0]}” atasözü “${a[1][1]}” anlamındadır.`),
      f(`“${n[0][0]}” cümlesinin sonuna ${ISAD[n[0][1]]} konur.`, `“${n[0][0]}” cümlesinin sonuna ${ISAD[n[0][1] === '.' ? '?' : '.']} konur.`),
      f(`“${e[2][0]}” sözcüğünün eş anlamlısı “${e[2][1]}” sözcüğüdür.`, `“${z[2][0]}” sözcüğünün eş anlamlısı “${z[2][1]}” sözcüğüdür.`)]; };
  const DIL = { gir: 'Öğretmen tahtaya sözcükler ve cümlelerle ilgili bilgiler yazdı.' };
  const dilCq = [
    r => { const e = kar(r, ES), z = kar(r, ZIT); return coktan(p(`${ADLAR[Math.floor(r() * 12)]} sözcük kartlarını eşleştiriyor.`), `“${e[0][0]}” sözcüğünün eş anlamlısı hangisidir?`, e[0][1], [z[0][1], e[1][1], z[1][0]]); },
    r => { const z = kar(r, ZIT), e = kar(r, ES); return coktan(p('Öğretmen tahtaya bir sözcük yazdı ve zıt anlamlısını sordu.'), `“${z[0][0]}” sözcüğünün zıt anlamlısı hangisidir?`, z[0][1], [e[0][1], z[1][1], e[1][0]]); },
    r => { const d = kar(r, DEYIM); return coktan(p('Öğretmen tahtaya bir deyim yazdı ve anlamını sordu.'), `“${d[0][0]}” deyiminin anlamı hangisidir?`, d[0][1], d.slice(1, 4).map(x => x[1])); },
    r => { const SEN = [['her gün kumbarasına biraz para atıyor. Bir yıl sonra bisiklet alacak kadar parası oldu.', 0], ['ödevini akşama bırakınca yetiştiremedi; ertesi gün ödevlerini hemen yapmaya karar verdi.', 1], ['ile arkadaşları sınıf panosunu birlikte hazırlayınca iş bir saatte bitti.', 2], ['eski kumaş parçalarını bir kutuda saklıyordu; okul tiyatrosunda kostüm gerekince hepsi işe yaradı.', 4]];
      const [sen, k] = SEN[Math.floor(r() * SEN.length)]; return coktan(p(`${ADLAR[Math.floor(r() * 12)]} ${sen}`), 'Bu durumu en iyi anlatan atasözü hangisidir?', ATA[k][0], kar(r, ATA.filter((_, i) => i !== k)).slice(0, 3).map(x => x[0])); },
    r => { const n = kar(r, NOKTA); return coktan(p('Bir öğrenci noktalama işaretlerini unutmuş.'), `“${n[0][0]}” cümlesinin sonuna hangi işaret konmalıdır?`, n[0][1] + ' (' + ISAD[n[0][1]] + ')', ['.', '?', '!', ','].filter(x => x !== n[0][1]).slice(0, 3).map(x => x + ' (' + (ISAD[x] || 'virgül') + ')')); },
  ];
  const SP = [
    (r, t) => [() => kodDY(DIL.gir + ' Bilgi doğruysa "Doğru", yanlışsa "Yanlış" bölümündeki rakamı boyayacaksınız.', kar(r, dilSt(r)).slice(0, 4), t + 'k'),
      () => yolDY(DIL.gir + ' Öğrenciler ifade doğruysa "D", yanlışsa "Y" okunu izliyor.', kar(r, dilSt(r)).slice(0, 3), t + 'y'),
      () => kapDY(DIL.gir + ' Bilgi doğruysa "Doğru Bilgi", yanlışsa "Yanlış Bilgi" kabına atılıyor.', kar(r, dilSt(r)).slice(0, 5), t + 'p')],
    (r, t, M) => [() => { let l, n = 0; do { l = kar(r, dilSt(r)).slice(0, 3); } while (!l.some(x => x[1]) && ++n < 50); return roma(p(DIL.gir), 'Buna göre yukarıdaki ifadelerden hangileri doğrudur?', l); },
      () => sirala('Metindeki olaylar karışık verilmiştir.', M.sira, 'Olayların oluş sırası hangisidir?', t + 's'),
      () => { const e = kar(r, ES).slice(0, 4); return esle('Soldaki sözcükleri sağdaki eş anlamlılarıyla eşleştiriniz.', e, 'Buna göre eşleştirme hangi seçenekte doğru verilmiştir?', t + 'e'); }],
    (r, t) => [() => kacTane(p(DIL.gir), kar(r, dilSt(r)).slice(0, 4)),
      () => kareYol(DIL.gir + ' ' + ADLAR[Math.floor(r() * 12)] + ' bu bilgilerle bir kare oyunu oynuyor.', kar(r, dilSt(r)).slice(0, 4), t + 'q', 1, 1),
      () => { const s = dilSt(r).concat(dilSt(r)); const y = s.find(x => !x[1]) || s[0], d = kar(r, s.filter(x => x[1])).slice(0, 3); return cocukSec(p('Dört arkadaş sözcükler ve cümlelerle ilgili bildiklerini söylüyor.'), 'Buna göre hangi çocuğun söylediği yanlıştır?', [y[0], ...d.map(x => x[0])], t + 'c'); }],
  ];
  const metinKutu = M => `<div class="t4-metin"><b>${M.baslik}</b>${M.metin.map(x => `<p>${x}</p>`).join('')}</div>`;
  const W = (hafta, unite, baslik, konu, M) => ({ unite, hafta, baslik, konu, sayfalar: () => {
    yeniHafta(); const r = RNG('t4-' + hafta), t = 't4h' + hafta, c = (hafta - 1) % 3;
    const sp = SP[c](r, t, M), mq = M.sorular.map(([k, d, y]) => () => coktan('', k, d, y)), dq = kar(r, dilCq);
    const [s0, s1] = M.sozcuk;
    const A = [ortak(metinKutu(M), mq.slice(0, 3)), sp[0](), coktan(p(`Metinde geçen “${s0}” sözcüğünü düşününüz.`), `“${s0}” sözcüğünün metindeki anlamı hangisidir?`, s1[0], s1.slice(1))];
    const B = [mq[3](), sp[1](), sp[2](), dq[0](r), dq[1](r), mq[4] ? mq[4]() : dq[2](r)];
    return [sayfa(A).replace('soruları aşağıdaki bilgilere göre', 'soruları aşağıdaki metne göre'), sayfa(B).replace(/<\/div>$/, optik() + '</div>'), cevapSayfasi(`${hafta}. hafta · ${baslik}`)];
  } });

  // ——— Haftalar: özgün metinler ———
  const T4 = {
    'hafta-01': W(1, 1, 'Türkçe Konuşalım', 'Okuma kültürü · Türkçe konuşma, eş ve zıt anlam', { baslik: 'Kafedeki Tabela',
      metin: ['Defne, babasıyla yeni açılan bir kafeye gitti. Kapının üstündeki büyük tabelada “Coffee Point” yazıyordu. Menüde de “cheesecake”, “brownie”, “smoothie” gibi sözcükler vardı.',
        'Defne garsona dönüp “Bu tatlıların Türkçe adları yok mu?” diye sordu. Garson gülümsedi: “Var tabii, peynirli pasta, çikolatalı kek, meyveli içecek…” Defne şaşırdı. “O zaman neden Türkçesini yazmıyorsunuz?” dedi.',
        'Eve dönünce Defne bir mektup yazdı. Mektubunda dilimizin çok zengin olduğunu, her şeyin güzel bir Türkçe karşılığı bulunduğunu anlattı. Birkaç hafta sonra kafenin önünden geçerken menünün değiştiğini gördü: “Peynirli pasta, çikolatalı kek, meyveli içecek.” Defne\'nin yüzü güldü.'],
      sorular: [['Defne\'nin garsona soru sormasının nedeni nedir?', 'Menüde yabancı sözcükler görmesi', ['Tatlıların pahalı olması', 'Kafenin kalabalık olması', 'Garsonun geç gelmesi']],
        ['Metnin ana fikri hangisidir?', 'Dilimizi korumalı, Türkçe karşılıkları kullanmalıyız.', ['Kafelerde tatlı yenmemelidir.', 'Mektup yazmak zordur.', 'Yabancı tatlılar daha lezzetlidir.']],
        ['Defne kafe için ne yapmıştır?', 'Kafeye bir mektup yazmıştır.', ['Kafeyi şikâyet etmiştir.', 'Kafede çalışmaya başlamıştır.', 'Kafeye bir tabela hediye etmiştir.']],
        ['Metindeki olaylardan hangisi en son olmuştur?', 'Menünün Türkçe yazıldığını görmesi', ['Kafeye gitmesi', 'Garsona soru sorması', 'Mektup yazması']],
        ['Metne en uygun başlık hangisidir?', 'Güzel Türkçemiz', ['Tatlı Tarifleri', 'Babamla Alışveriş', 'Kafenin Garsonu']]],
      sozcuk: ['zengin', ['çok çeşitli, bol', 'çok parası olan', 'yorgun', 'küçük']],
      sira: ['Defne kafeye gitti.', 'Menüde yabancı sözcükler gördü.', 'Garsona soru sordu.', 'Kafeye mektup yazdı.', 'Menünün değiştiğini gördü.'] }),
    'hafta-02': W(2, 1, 'Evimizdeki Kütüphane', 'Okuma kültürü · Kütüphane, metin türleri', { baslik: 'Raflardaki Dünya',
      metin: ['Kaan\'ın dedesinin evinde koca bir kitaplık vardı. Raflar tavana kadar uzanıyor, bazı kitapların kapakları yıllardan sararmış görünüyordu.',
        'Kaan bir gün dedesine sordu: “Bu kadar kitabı nasıl okudun?” Dedesi güldü: “Her gün biraz. Damlaya damlaya göl olur.” Sonra Kaan\'a bir öneride bulundu: Evlerinde küçük bir kütüphane kuracaklardı.',
        'Hafta sonu birlikte çalıştılar. Kitapları türlerine göre ayırdılar: masallar bir rafa, bilgi kitapları başka bir rafa, şiirler en alttaki rafa yerleşti. Kaan her kitabın sırtına küçük renkli etiketler yapıştırdı.',
        'Akşam annesi eve geldiğinde salonun köşesinde yepyeni bir kütüphane gördü. Kaan heyecanla “Artık her akşam yatmadan önce birlikte okuyabiliriz!” dedi.'],
      sorular: [['Dedenin “Damlaya damlaya göl olur.” sözüyle anlatmak istediği nedir?', 'Her gün biraz okuyarak çok kitap bitirilebilir.', ['Göl kenarında kitap okunmalıdır.', 'Yağmurlu günlerde okumak gerekir.', 'Kitaplar suya dayanıklıdır.']],
        ['Kaan ile dedesi kitapları neye göre ayırmıştır?', 'Türlerine göre', ['Renklerine göre', 'Fiyatlarına göre', 'Sayfa sayısına göre']],
        ['Metinde hangi soruya cevap bulunamaz?', 'Dede hangi yıl doğmuştur?', ['Kitaplar nasıl ayrılmıştır?', 'Kütüphane nereye kurulmuştur?', 'Kaan etiketleri nereye yapıştırmıştır?']],
        ['Kaan\'ın akşamki sözlerinden hangi duygusu anlaşılır?', 'Heyecan', ['Korku', 'Kıskançlık', 'Öfke']],
        ['Metinden hangi sonuca ulaşılır?', 'Okuma alışkanlığı aile içinde birlikte kazanılabilir.', ['Kitaplar yalnız kütüphanede okunur.', 'Eski kitaplar atılmalıdır.', 'Masallar en alt rafa konmalıdır.']]],
      sozcuk: ['sararmış', ['eskiyip rengi solmuş', 'yeni basılmış', 'yırtılmış', 'ıslanmış']],
      sira: ['Kaan dedesine kitapları sordu.', 'Dedesi ev kütüphanesi önerdi.', 'Kitapları türlerine göre ayırdılar.', 'Kitaplara etiket yapıştırdılar.', 'Annesi kütüphaneyi gördü.'] }),
    'hafta-03': W(3, 1, 'Yanlış Haber', 'Okuma kültürü · Doğru bilgiye ulaşma', { baslik: 'Herkes Paylaşıyordu',
      metin: ['Bir sabah sınıfın mesaj grubunda bir haber dolaşmaya başladı: “Yarın okullar tatil! Paylaşın!” Haberin altında ne bir kaynak ne de bir tarih vardı.',
        'Mert hemen haberi başka gruplara da göndermek istedi. Ama Zeynep onu durdurdu: “Bekle. Bu haber nereden çıktı? Önce okulun ve resmî kurumların sayfalarına bakalım.”',
        'İkisi birlikte okulun internet sitesini ve valiliğin duyurularını incelediler. Hiçbir yerde tatil kararı yoktu. Zeynep gruba bir mesaj yazdı: “Bu haber doğru değil. Resmî bir açıklama yok. Lütfen kaynağını bilmediğimiz haberleri paylaşmayalım.”',
        'Ertesi gün okul her zamanki gibi açıktı. Öğretmenleri Zeynep\'e teşekkür etti ve sınıfa “Bir haberi paylaşmadan önce kaynağını sorgulayın.” dedi.'],
      sorular: [['Zeynep haberin doğruluğunu nasıl araştırmıştır?', 'Resmî kurumların sayfalarına bakarak', ['Arkadaşlarına sorarak', 'Haberi daha çok paylaşarak', 'Televizyonu açarak']],
        ['Haberle ilgili hangisi söylenebilir?', 'Kaynağı belirsiz bir haberdir.', ['Valilik tarafından yayımlanmıştır.', 'Okul tarafından yazılmıştır.', 'Gerçekleşmiş bir olaydır.']],
        ['Metnin konusu hangisidir?', 'Yanlış haberleri doğrulamadan paylaşmamak', ['Okulların tatil olması', 'Mesaj gruplarının kurulması', 'Valiliğin görevleri']],
        ['Öğretmenin sözünden hangi öğüt çıkarılır?', 'Bilgiyi paylaşmadan önce kaynağını kontrol etmeliyiz.', ['Mesaj gruplarına hiç girmemeliyiz.', 'Her haberi hemen paylaşmalıyız.', 'Okula gitmeden önce haber okumalıyız.']],
        ['Metindeki kişilerden hangisi aceleci davranmıştır?', 'Mert', ['Zeynep', 'Öğretmen', 'Valilik görevlisi']]],
      sozcuk: ['resmî', ['devlet ya da kurum tarafından yapılan', 'çok eğlenceli', 'gizli', 'eski']],
      sira: ['Gruba tatil haberi geldi.', 'Mert haberi paylaşmak istedi.', 'Zeynep resmî sayfalara baktı.', 'Zeynep gruba açıklama yazdı.', 'Okul her zamanki gibi açıldı.'] }),
    'hafta-04': W(4, 1, 'Kitaplar Ne İşe Yarar?', 'Okuma kültürü · Okumanın yararları, hikâye unsurları', { baslik: 'Hikâyesi Olmayan Kitap',
      metin: ['Kütüphanenin en üst rafında bembeyaz sayfaları olan bir kitap yaşıyordu. Diğer kitaplar ondan ilginç hikâyeler bekliyordu ama onun içinde tek bir satır bile yoktu.',
        'Bir gün Ecrin kütüphaneye geldi ve beyaz kitabı eline aldı. Sayfaları boş görünce önce şaşırdı, sonra gülümsedi. Kalemini çıkardı ve ilk sayfaya yazmaya başladı: “Bir zamanlar, denizin dibinde konuşan bir deniz kaplumbağası varmış…”',
        'Ecrin her hafta kütüphaneye gelip birkaç sayfa yazdı. Kaplumbağanın maceraları büyüdükçe kitap da mutlu oluyordu. Yıl sonunda kitap baştan sona dolmuştu.',
        'Kütüphaneci kitabı rafın en önüne koydu. Artık çocuklar sırayla onu okumak istiyordu. Hikâyesi olmayan kitap, en çok okunan kitap olmuştu.'],
      sorular: [['Hikâyedeki olaylar nerede geçmektedir?', 'Kütüphanede', ['Denizin dibinde', 'Ecrin\'in evinde', 'Okul bahçesinde']],
        ['Kitabın üzgün olmasının nedeni nedir?', 'İçinde hiç yazı olmaması', ['Yırtılmış olması', 'Rafın en altında durması', 'Çok kalın olması']],
        ['Hikâyenin ana karakterleri kimlerdir?', 'Beyaz kitap ve Ecrin', ['Kütüphaneci ve deniz', 'Kaplumbağa ve balık', 'Diğer kitaplar ve öğretmen']],
        ['Hikâyenin sonunda kitapta nasıl bir değişiklik olmuştur?', 'En çok okunan kitap olmuştur.', ['Atılmıştır.', 'Satılmıştır.', 'Yeniden bembeyaz olmuştur.']],
        ['Bu hikâyeden hangi sonuç çıkarılır?', 'Yazmak ve okumak kitaplara hayat verir.', ['Boş kitaplar işe yaramaz.', 'Kütüphanelere gitmemeliyiz.', 'Deniz kaplumbağaları konuşur.']]],
      sozcuk: ['macera', ['heyecanlı, ilginç olaylar', 'kitap kapağı', 'sessiz bir yer', 'yemek tarifi']],
      sira: ['Beyaz kitap rafta bekliyordu.', 'Ecrin beyaz kitabı buldu.', 'Ecrin ilk sayfaya yazdı.', 'Kitap baştan sona doldu.', 'Kütüphaneci kitabı öne koydu.'] }),
    'hafta-05': W(5, 2, 'Gözüm Arkada Kalmayacak', 'Millî Mücadele ve Atatürk · Duygular, neden-sonuç', { baslik: 'Cepheye Giden Mektup',
      metin: ['1921 yılının soğuk bir kış gecesiydi. Kastamonu\'da küçük bir köyde yaşayan Ayşe Nine, oğlunun cepheden gönderdiği mektubu tekrar tekrar okuyordu.',
        'Mektupta oğlu, askerlerin kışlık giyecek ihtiyacından söz ediyordu. Ayşe Nine ertesi sabah köyün kadınlarını topladı. Herkes evindeki yünü getirdi. Günlerce çorap, eldiven ve yelek ördüler.',
        'Örülen giyecekler sandıklara yerleştirildi ve kağnılarla cepheye gönderildi. Kağnıları süren kadınlar karla kaplı yollarda günlerce yürüdü.',
        'Birkaç hafta sonra Ayşe Nine\'ye yeni bir mektup geldi. Oğlu, “Anneciğim, ördüğünüz çoraplar ayaklarımızı ısıtıyor. Gözünüz arkada kalmasın, vatanı koruyacağız.” diye yazmıştı. Ayşe Nine mektubu göğsüne bastırdı ve gözleri doldu.'],
      sorular: [['Köyün kadınlarının çorap ve eldiven örmesinin nedeni nedir?', 'Askerlerin kışlık giyeceğe ihtiyacı olması', ['Köyde pazar kurulacak olması', 'Kadınların yarışma yapması', 'Yünlerin satılamaması']],
        ['Giyecekler cepheye nasıl gönderilmiştir?', 'Kağnılarla', ['Trenle', 'Uçakla', 'Gemiyle']],
        ['Metinden Millî Mücadele ile ilgili hangi sonuca ulaşılır?', 'Halk ve ordu birlik içinde mücadele etmiştir.', ['Savaşı yalnız askerler kazanmıştır.', 'Köylüler savaşla ilgilenmemiştir.', 'Mektuplar cepheye ulaşmamıştır.']],
        ['Ayşe Nine\'nin son mektubu okurken gözlerinin dolmasının nedeni hangisidir?', 'Oğlunun sözlerinden duygulanması', ['Mektubun yanlış adrese gelmesi', 'Çorapların kaybolması', 'Hava çok soğuk olduğu için üşümesi']],
        ['“Gözünüz arkada kalmasın.” sözüyle anlatılmak istenen nedir?', 'Merak etmeyin, endişelenmeyin.', ['Arkanıza dikkatle bakın.', 'Gözlerinize iyi bakın.', 'Yola geriye dönerek gidin.']]],
      sozcuk: ['cephe', ['savaşın yapıldığı yer', 'bir evin önü', 'okul bahçesi', 'köy meydanı']],
      sira: ['Ayşe Nine oğlunun mektubunu okudu.', 'Köyün kadınlarını topladı.', 'Kadınlar çorap ve eldiven ördü.', 'Giyecekler kağnılarla gönderildi.', 'Oğlundan yeni mektup geldi.'] }),
    'hafta-06': W(6, 2, 'İstiklal Marşı\'nın Şairi', 'Millî Mücadele ve Atatürk · Mehmet Âkif Ersoy, bilgilendirici metin', { baslik: 'Mehmet Âkif Ersoy',
      metin: ['Mehmet Âkif Ersoy 1873 yılında İstanbul\'da doğdu. Küçük yaşlardan itibaren kitap okumayı ve şiir yazmayı çok sevdi. Veteriner hekim olarak çalıştı, aynı zamanda birçok şiir yazdı.',
        'Kurtuluş Savaşı yıllarında Anadolu\'yu dolaşarak halkı birlik olmaya çağıran konuşmalar yaptı. 1921 yılında Türkiye Büyük Millet Meclisi bir millî marş yarışması düzenledi.',
        'Mehmet Âkif, yarışma için para ödülü verileceği için önce katılmak istemedi. Ödülün kendisine verilmemesi şartıyla şiirini gönderdi. Şiiri Meclis\'te büyük bir coşkuyla kabul edildi. Bu şiir, İstiklal Marşı\'mızdır.',
        'Mehmet Âkif, İstiklal Marşı\'nı “Allah bu millete bir daha İstiklal Marşı yazdırmasın.” sözüyle anlatırdı. Onun bu sözü, marşın ne zor günlerde yazıldığını gösterir.'],
      sorular: [['Mehmet Âkif Ersoy\'un mesleği hangisidir?', 'Veteriner hekim', ['Öğretmen', 'Mühendis', 'Asker']],
        ['Mehmet Âkif yarışmaya önce neden katılmak istememiştir?', 'Yarışmada para ödülü verileceği için', ['Şiir yazmayı sevmediği için', 'Hasta olduğu için', 'İstanbul\'da olmadığı için']],
        ['İstiklal Marşı hangi yıl kabul edilmiştir?', '1921', ['1873', '1923', '1919']],
        ['Metnin türü hangisidir?', 'Bilgilendirici metin', ['Masal', 'Fıkra', 'Şiir']],
        ['Metne göre Mehmet Âkif\'in hangi özelliğinden söz edilemez?', 'Ressam olduğundan', ['Şiir yazdığından', 'Halkı birliğe çağırdığından', 'Kitap okumayı sevdiğinden']]],
      sozcuk: ['coşku', ['büyük sevinç ve heyecan', 'derin üzüntü', 'korku', 'yorgunluk']],
      sira: ['Mehmet Âkif İstanbul\'da doğdu.', 'Veteriner hekim olarak çalıştı.', 'Meclis marş yarışması düzenledi.', 'Mehmet Âkif şiirini gönderdi.', 'Şiir İstiklal Marşı olarak kabul edildi.'] }),
    'hafta-07': W(7, 2, 'Mehmetçiğe Botlar', 'Millî Mücadele ve Atatürk · Dinleme, olay sırası', { baslik: 'Hasan Usta\'nın Tezgâhı',
      metin: ['Ankara\'nın dar bir sokağında küçük bir ayakkabıcı dükkânı vardı. Dükkânın sahibi Hasan Usta, yıllardır mahallenin ayakkabılarını onarırdı.',
        'Bir gün dükkâna bir asker geldi. Ayağındaki çarık delik deşikti. Asker, cephede birçok arkadaşının yalınayak yürüdüğünü anlattı. Hasan Usta o gece uyuyamadı.',
        'Ertesi sabah çıraklarını topladı: “Bundan sonra kazandığımız her kuruşla deri alacağız. Askerlerimize bot dikeceğiz.” Çıraklar sevinçle işe koyuldu. Komşular da evlerindeki eski deri eşyaları getirdi.',
        'Haftalar boyunca dükkânın ışığı hiç sönmedi. Dikilen yüzlerce bot sandıklara konup cepheye gönderildi. Aylar sonra Hasan Usta\'ya bir mektup geldi. Mektupta yalnızca bir cümle vardı: “Ayaklarımız artık üşümüyor, usta!”'],
      sorular: [['Hasan Usta\'nın gece uyuyamamasının nedeni nedir?', 'Askerlerin yalınayak kaldığını öğrenmesi', ['Dükkânının kapanması', 'Çok yorulması', 'Komşularıyla tartışması']],
        ['Komşuların davranışı neyi gösterir?', 'Halkın yardımlaşmaya katıldığını', ['Komşuların ayakkabı sattığını', 'Herkesin dükkânı kıskandığını', 'Eşyaların artık işe yaramadığını']],
        ['“Dükkânın ışığı hiç sönmedi.” cümlesiyle anlatılmak istenen nedir?', 'Gece gündüz çalışıldığı', ['Lambanın bozulduğu', 'Dükkânın satıldığı', 'Elektrik kesintisi olduğu']],
        ['Mektuptaki cümleden askerlerin hangi duygusu anlaşılır?', 'Minnet', ['Öfke', 'Korku', 'Kıskançlık']],
        ['Metnin ana fikri hangisidir?', 'Zor günlerde herkes elinden geleni yaparak ülkesine destek olur.', ['Ayakkabılar deriden yapılmalıdır.', 'Çıraklar ustalarını dinlemelidir.', 'Mektuplar kısa yazılmalıdır.']]],
      sozcuk: ['çarık', ['ham deriden yapılan ayakkabı', 'asker şapkası', 'bir tür ekmek', 'kalın palto']],
      sira: ['Dükkâna bir asker geldi.', 'Hasan Usta uyuyamadı.', 'Çıraklarını topladı.', 'Botlar cepheye gönderildi.', 'Cepheden mektup geldi.'] }),
    'hafta-08': W(8, 2, 'Çanakkale', 'Millî Mücadele ve Atatürk · Bilgilendirici metin, şiir okuma', { baslik: 'Geçilmeyen Boğaz',
      metin: ['Çanakkale Boğazı, Ege Denizi\'ni Marmara Denizi\'ne bağlayan dar bir su yoludur. 1915 yılında güçlü devletlerin donanmaları bu boğazı geçip İstanbul\'a ulaşmak istedi.',
        '18 Mart 1915\'te düşman gemileri boğaza girdi. Kıyıdaki topçularımız gemilere karşı kahramanca savaştı. Seyit Onbaşı adlı bir askerimiz, top mermisini kaldıran makine bozulunca çok ağır bir mermiyi sırtında taşıyarak topa yerleştirdi. Bu mermi bir düşman gemisine isabet etti.',
        'O gün düşman donanması büyük kayıplar verdi ve geri çekildi. Ardından karada aylarca süren savaşlar yapıldı. Sonunda düşman Çanakkale\'yi geçemedi.',
        'Her yıl 18 Mart\'ta Çanakkale Zaferi\'ni ve şehitlerimizi saygıyla anarız. “Çanakkale geçilmez!” sözü, o günlerin kahramanlığını bugüne taşır.'],
      sorular: [['Düşman donanması boğazı geçip nereye ulaşmak istemiştir?', 'İstanbul\'a', ['Ankara\'ya', 'İzmir\'e', 'Bursa\'ya']],
        ['Seyit Onbaşı mermiyi neden sırtında taşımıştır?', 'Mermiyi kaldıran makine bozulduğu için', ['Mermi çok hafif olduğu için', 'Komutanı ona kızdığı için', 'Topun yerini değiştirmek için']],
        ['Metne göre 18 Mart hangi olayın yıl dönümüdür?', 'Çanakkale Deniz Zaferi', ['Cumhuriyetin ilanı', 'Meclisin açılışı', 'İstiklal Marşı\'nın kabulü']],
        ['Metinde hangi soruya cevap yoktur?', 'Seyit Onbaşı nerede doğmuştur?', ['Çanakkale Boğazı hangi denizleri bağlar?', 'Düşman ne zaman boğaza girdi?', '18 Mart\'ta ne yaparız?']],
        ['Metnin türü hangisidir?', 'Bilgilendirici metin', ['Masal', 'Fabl', 'Fıkra']]],
      sozcuk: ['donanma', ['bir devletin savaş gemilerinin tamamı', 'bayram süsü', 'kale duvarı', 'askerî okul']],
      sira: ['Düşman İstanbul\'a ulaşmak istedi.', 'Gemiler boğaza girdi.', 'Seyit Onbaşı mermiyi taşıdı.', 'Düşman donanması geri çekildi.', 'Karada savaşlar sürdü.'] }),
    'hafta-09': W(9, 2, 'Anafartalar Kahramanı', 'Millî Mücadele ve Atatürk · Ana fikir, söz varlığı', { baslik: 'Conkbayırı\'nda Bir Sabah',
      metin: ['Çanakkale\'de karada savaşlar sürerken genç bir komutan dikkat çekiyordu: Yarbay Mustafa Kemal. Düşmanın hangi tepeden saldıracağını önceden tahmin ediyor, askerlerini doğru yere yerleştiriyordu.',
        'Bir sabah düşman askerleri Conkbayırı\'na doğru ilerlemeye başladı. Mustafa Kemal, cephaneleri bitmiş askerlerle karşılaştı. Onlara süngü takıp yere yatmalarını söyledi. Askerler yere yatınca düşman da durdu. Bu kısa zaman, yardımın yetişmesini sağladı.',
        'Bir başka gün Mustafa Kemal saldırı sırasında göğsünden vuruldu. Cebindeki saat mermiyi durdurmuş, onu kurtarmıştı. O, askerlerinin moralini bozmamak için yarasını kimseye göstermedi.',
        'Mustafa Kemal\'in cesareti ve kararlılığı Çanakkale Zaferi\'nde büyük rol oynadı. Bu zafer, daha sonra Kurtuluş Savaşı\'nı yönetecek liderin adını bütün yurda duyurdu.'],
      sorular: [['Mustafa Kemal askerlere neden yere yatmalarını söylemiştir?', 'Düşmanı durdurup zaman kazanmak için', ['Askerler yorulduğu için', 'Hava çok sıcak olduğu için', 'Saklambaç oynamak için']],
        ['Mustafa Kemal\'i ölümden ne kurtarmıştır?', 'Cebindeki saat', ['Miğferi', 'Askerleri', 'Atı']],
        ['Mustafa Kemal yarasını neden göstermemiştir?', 'Askerlerinin morali bozulmasın diye', ['Doktora gitmek istemediği için', 'Yarası hiç acımadığı için', 'Saatini kaybettiği için']],
        ['Metinde Mustafa Kemal\'in hangi özelliği vurgulanmamıştır?', 'Resim yapmayı sevmesi', ['Cesaret', 'Kararlılık', 'İleri görüşlülük']],
        ['Metnin ana fikri hangisidir?', 'Mustafa Kemal\'in cesareti ve kararlılığı zaferde önemli rol oynamıştır.', ['Saatler mermiyi durdurur.', 'Savaşta herkes yere yatmalıdır.', 'Tepeler savaş için uygun değildir.']]],
      sozcuk: ['moral', ['gönül gücü, yaşama sevinci', 'askerî rütbe', 'bir tür silah', 'yorgunluk']],
      sira: ['Mustafa Kemal düşmanın yolunu tahmin etti.', 'Düşman Conkbayırı\'na ilerledi.', 'Askerler yere yattı.', 'Yardım yetişti.', 'Zafer kazanıldı.'] }),
    'hafta-10': W(10, 3, 'İyileştirici Güç', 'Erdemler · Sevgi, duygular', { baslik: 'Kuşun Kanadı',
      metin: ['Teneffüste bahçede oynayan Alp, çitin dibinde kanadı yaralanmış küçük bir serçe gördü. Serçe uçmaya çalışıyor ama başaramıyordu.',
        'Alp, serçeyi bir kutuya koydu ve hemen öğretmenine götürdü. Öğretmeni okulun yakınındaki veteriner kliniğini aradı. Okul çıkışı Alp, annesiyle birlikte serçeyi veterinere götürdü.',
        'Veteriner kanadı sardı ve “Bir hafta dinlenmesi gerekiyor.” dedi. Alp bir hafta boyunca serçeye su ve tohum verdi, onu sıcak bir köşede tuttu. Her sabah onunla konuşuyor, adını “Pırpır” koymuştu.',
        'Bir hafta sonra Alp, Pırpır\'ı bahçeye çıkardı. Serçe önce biraz bekledi, sonra kanatlarını çırpıp ağaca kondu. Alp\'in gözleri doldu ama yüzü gülüyordu. Annesi “Sevgi en iyi ilaçtır.” dedi.'],
      sorular: [['Alp serçeyi ilk olarak kime götürmüştür?', 'Öğretmenine', ['Veterinere', 'Annesine', 'Arkadaşına']],
        ['Serçe neden uçamıyordu?', 'Kanadı yaralandığı için', ['Çok küçük olduğu için', 'Aç olduğu için', 'Kutuda kapalı kaldığı için']],
        ['Metnin sonunda Alp\'in duyguları için hangisi söylenebilir?', 'Hem hüzünlü hem mutludur.', ['Yalnız öfkelidir.', 'Korkmuştur.', 'Hiçbir şey hissetmemiştir.']],
        ['“Sevgi en iyi ilaçtır.” sözüyle anlatılmak istenen nedir?', 'Sevgi ve ilgi iyileşmeye yardım eder.', ['İlaç almaya gerek yoktur.', 'Sevgi eczanede satılır.', 'Kuşlar ilaç sevmez.']],
        ['Metne en uygun başlık hangisidir?', 'Pırpır\'ın İyileşmesi', ['Okul Bahçesi', 'Veterinerin Kliniği', 'Ağaçtaki Yuva']]],
      sozcuk: ['çırpmak', ['kanatları hızlıca açıp kapamak', 'suya dalmak', 'yemek pişirmek', 'ağaca tırmanmak']],
      sira: ['Alp yaralı serçeyi buldu.', 'Serçeyi öğretmenine götürdü.', 'Veteriner kanadı sardı.', 'Alp bir hafta serçeye baktı.', 'Serçe ağaca kondu.'] }),
    'hafta-11': W(11, 3, 'Maysa ile Bulut', 'Erdemler · Empati, arkadaşlık', { baslik: 'Yeni Sıra Arkadaşı',
      metin: ['Sınıfa yeni bir öğrenci geldi. Adı Maysa\'ydı. Başka bir ülkeden göç etmişlerdi ve Maysa Türkçeyi yeni öğreniyordu. İlk günler kimseyle konuşmadı, teneffüste hep yalnız oturdu.',
        'Bulut bir gün Maysa\'nın defterine resimler çizdiğini gördü. Resimler çok güzeldi. Yanına oturdu ve resimleri gösterip “Bu ne?” diye sordu. Maysa gülümsedi ve resimdeki şeyin adını kendi dilinde söyledi. Bulut da Türkçesini söyledi.',
        'O günden sonra her teneffüs bir oyun gibi geçti. Maysa resim çiziyor, Bulut Türkçesini söylüyordu. Maysa da Bulut\'a kendi dilinden sözcükler öğretiyordu.',
        'Ay sonunda Maysa, sınıf panosuna kocaman bir resim astı. Resimde el ele tutuşmuş iki çocuk vardı. Altında yeni öğrendiği iki sözcük yazıyordu: “Benim arkadaşım.”'],
      sorular: [['Maysa ilk günler neden kimseyle konuşmamıştır?', 'Türkçeyi yeni öğrendiği için', ['Konuşmayı sevmediği için', 'Hasta olduğu için', 'Arkadaşlarına kızdığı için']],
        ['Bulut ile Maysa\'nın arkadaşlığı nasıl başlamıştır?', 'Bulut, Maysa\'nın resimleriyle ilgilenince', ['Öğretmen onları eşleştirince', 'Aynı sokakta oturdukları için', 'Bir yarışmada tanışınca']],
        ['Bulut\'un davranışı hangi değere örnektir?', 'Empati ve yardımseverlik', ['Kıskançlık', 'Bencillik', 'Tembellik']],
        ['Panodaki resmin altındaki yazı neyi gösterir?', 'Maysa\'nın Türkçe öğrendiğini ve arkadaş edindiğini', ['Maysa\'nın okulu bırakacağını', 'Resmi Bulut\'un çizdiğini', 'Maysa\'nın resim yarışması kazandığını']],
        ['Metnin konusu hangisidir?', 'Farklı dillerden iki çocuğun arkadaşlığı', ['Resim yarışması', 'Göç yolculuğu', 'Okul panosunun süslenmesi']]],
      sozcuk: ['göç etmek', ['yaşadığı yeri bırakıp başka yere yerleşmek', 'tatile gitmek', 'okula başlamak', 'resim çizmek']],
      sira: ['Maysa sınıfa geldi.', 'Teneffüste yalnız oturdu.', 'Bulut resimleri fark etti.', 'Birbirlerine sözcük öğrettiler.', 'Maysa panoya resim astı.'] }),
    'hafta-12': W(12, 3, 'Hasta Ziyareti', 'Erdemler · Görgü kuralları, yönerge', { baslik: 'Dedemi Ziyaret',
      metin: ['Kerem\'in dedesi ameliyat olmuştu ve birkaç gün hastanede kalacaktı. Kerem annesiyle birlikte onu ziyarete gitmek istedi.',
        'Yola çıkmadan önce annesi Kerem\'e hasta ziyaretinin kurallarını anlattı: “Ziyareti kısa tutacağız. Hastanede yüksek sesle konuşmayacağız. Dedeni yoracak sorular sormayacağız. Hastaneye girmeden ve çıkarken ellerimizi yıkayacağız.”',
        'Kerem dedesine bir hediye götürmek istedi. Önce çikolata almayı düşündü ama annesi doktorun dedesine şeker yasakladığını söyledi. Sonunda Kerem dedesi için bir resim çizdi ve altına “Çabuk iyileş dedeciğim!” yazdı.',
        'Odaya girdiklerinde dedesi resmi görünce çok sevindi. Kerem kısa bir süre dedesinin elini tuttu, okulda olanları anlattı. Yirmi dakika sonra vedalaştılar. Dedesi gülümseyerek “Bu resim bütün ilaçlardan iyi geldi.” dedi.'],
      sorular: [['Annesine göre hasta ziyaretinde hangisi yapılmamalıdır?', 'Yüksek sesle konuşmak', ['Ziyareti kısa tutmak', 'Ellerini yıkamak', 'Hastaya moral vermek']],
        ['Kerem neden çikolata götürmekten vazgeçmiştir?', 'Dedesine şeker yasak olduğu için', ['Çikolata pahalı olduğu için', 'Markete gidemediği için', 'Dedesi çikolata sevmediği için']],
        ['Ziyaret ne kadar sürmüştür?', 'Yirmi dakika', ['Bir saat', 'Bütün gün', 'Beş dakika']],
        ['Dedesinin son sözünden hangi sonuç çıkarılır?', 'Resim dedesini çok mutlu etmiştir.', ['Dedesi ilaç almayacaktır.', 'Resim bir ilaçtır.', 'Dedesi taburcu olmuştur.']],
        ['Metinde anlatılan kurallar hangi konuyla ilgilidir?', 'Hasta ziyareti görgü kuralları', ['Trafik kuralları', 'Oyun kuralları', 'Kütüphane kuralları']]],
      sozcuk: ['vedalaşmak', ['ayrılırken birbirine iyi dileklerde bulunmak', 'tanışmak', 'kavga etmek', 'hediye almak']],
      sira: ['Dede ameliyat oldu.', 'Annesi kuralları anlattı.', 'Kerem resim çizdi.', 'Hastanede dedesini ziyaret ettiler.', 'Vedalaşıp ayrıldılar.'] }),
    'hafta-13': W(13, 3, 'Çiftçi ve Oğulları', 'Erdemler · Çalışkanlık, fabl', { baslik: 'Tarladaki Hazine',
      metin: ['Bir zamanlar yaşlı bir çiftçinin üç oğlu vardı. Oğulları çok tembeldi; tarlada çalışmak yerine bütün gün gölgede uyurlardı.',
        'Çiftçi yaşlanıp hastalanınca oğullarını yanına çağırdı: “Tarlamızın toprağının altında bir hazine var. Onu bulursanız hiç sıkıntı çekmezsiniz.” dedi.',
        'Babaları vefat ettikten sonra üç kardeş kazmalarını alıp tarlaya koştu. Tarlanın her köşesini kazdılar, toprağı alt üst ettiler ama hiçbir sandık bulamadılar. Yorgun ve hayal kırıklığı içinde, kazdıkları tarlaya buğday ektiler.',
        'Yaz geldiğinde tarla altın sarısı başaklarla doldu. Hasat o kadar boldu ki kardeşler o yıl ilk kez bol para kazandı. En büyük kardeş başakların arasında durup gülümsedi: “Babamızın sözünü şimdi anladım. Hazine, emeğin kendisiymiş.”'],
      sorular: [['Kardeşler tarlayı neden kazmıştır?', 'Hazine bulmak için', ['Kuyu açmak için', 'Ev yapmak için', 'Ağaç dikmek için']],
        ['Babanın sözündeki “hazine” aslında nedir?', 'Çalışarak elde edilen ürün', ['Toprağa gömülü altın', 'Eski bir sandık', 'Kardeşlerin evi']],
        ['Hikâyenin başında kardeşlerin hangi özelliği vardır?', 'Tembellik', ['Çalışkanlık', 'Cömertlik', 'Cesaret']],
        ['Bu hikâyeden çıkarılabilecek ders hangisidir?', 'Emek vermeden kazanç elde edilmez.', ['Tarlada hazine aranmalıdır.', 'Babalar her zaman şaka yapar.', 'Buğday yazın ekilir.']],
        ['Hikâyeye en uygun atasözü hangisidir?', 'Emek olmadan yemek olmaz.', ['Damlaya damlaya göl olur.', 'Ağaç yaşken eğilir.', 'Komşu komşunun külüne muhtaçtır.']]],
      sozcuk: ['hasat', ['olgunlaşan ürünü toplama', 'tohum ekme', 'tarlayı sulama', 'toprağı kazma']],
      sira: ['Çiftçi oğullarını çağırdı.', 'Hazineden söz etti.', 'Kardeşler tarlayı kazdı.', 'Tarlaya buğday ektiler.', 'Bol hasat yaptılar.'] }),
    'hafta-14': W(14, 4, 'Bilim Nedir?', 'Bilim ve teknoloji · Bilgilendirici metin, soru sorma', { baslik: 'Neden Diye Soranlar',
      metin: ['Bilim, çevremizdeki olayları merak edip sorular sormakla başlar. Bir elmanın neden yere düştüğünü, gökyüzünün neden mavi olduğunu ya da bitkilerin nasıl büyüdüğünü merak etmek bilimin ilk adımıdır.',
        'Bilim insanları sorularına cevap bulmak için gözlem yapar, deneyler tasarlar ve sonuçları kaydeder. Bir deneyin sonucu ilk seferde istenen gibi çıkmayabilir. Bu durumda deney yeniden yapılır, hatalar düzeltilir.',
        'Bilimsel bilgi değişebilir. Yeni araçlar geliştikçe ve yeni gözlemler yapıldıkça eski bilgiler güncellenir. Örneğin teleskop icat edilmeden önce gökyüzündeki birçok gök cismi bilinmiyordu.',
        'Sen de bir bilim insanı gibi düşünebilirsin. Merak ettiğin bir soruyu yaz, nasıl cevap bulabileceğini planla ve gözlemlerini bir deftere kaydet. Unutma, her büyük buluş küçük bir “Neden?” sorusuyla başlar.'],
      sorular: [['Metne göre bilim neyle başlar?', 'Merak edip soru sormakla', ['Kitap ezberlemekle', 'Laboratuvar kurmakla', 'Ödül kazanmakla']],
        ['Deney istenen sonucu vermezse ne yapılır?', 'Deney yeniden yapılır, hatalar düzeltilir.', ['Deneyden vazgeçilir.', 'Sonuç gizlenir.', 'Başka bir konuya geçilir.']],
        ['Teleskop örneği hangi düşünceyi desteklemek için verilmiştir?', 'Bilimsel bilgi yeni araçlarla değişebilir.', ['Gökyüzü her zaman mavidir.', 'Teleskoplar çok pahalıdır.', 'Gök cisimleri hiç değişmez.']],
        ['Metnin son paragrafında okura ne önerilmektedir?', 'Bir bilim insanı gibi soru sorup gözlem yapması', ['Teleskop satın alması', 'Elma yemesi', 'Deney yapmaktan kaçınması']],
        ['Metnin türü hangisidir?', 'Bilgilendirici metin', ['Masal', 'Şiir', 'Fıkra']]],
      sozcuk: ['güncellemek', ['yeni bilgilere göre yenilemek', 'silip atmak', 'ezberlemek', 'saklamak']],
      sira: ['Bir olayı merak etmek', 'Soru sormak', 'Deney tasarlamak', 'Sonuçları kaydetmek', 'Gerekirse deneyi tekrarlamak'] }),
    'hafta-15': W(15, 4, 'Sporun Arkasındaki Bilim', 'Bilim ve teknoloji · Bilgilendirici metin, sebep-sonuç', { baslik: 'Saniyenin Yüzde Biri',
      metin: ['Olimpiyat oyunlarında bazen birinci ile ikinci arasındaki fark saniyenin yüzde biri kadardır. Bu kadar küçük bir farkı gözle görmek imkânsızdır. Bu yüzden yarışlarda elektronik zaman ölçerler kullanılır.',
        'Koşucular yarışa başlarken ayaklarını özel bir takoza yerleştirir. Takozun içindeki algılayıcılar, bir sporcu başlama işaretinden önce harekete geçerse bunu hemen fark eder.',
        'Spor giysileri de bilimle tasarlanır. Yüzücülerin mayoları suyun sürtünmesini azaltacak biçimde üretilir. Koşu ayakkabılarının tabanı ise her adımda ayağa geri itme sağlayacak şekilde yapılır.',
        'Yine de hiçbir teknoloji sporcunun emeğinin yerini tutamaz. Düzenli antrenman, sağlıklı beslenme ve kararlılık olmadan madalya kazanmak mümkün değildir.'],
      sorular: [['Yarışlarda elektronik zaman ölçer kullanılmasının nedeni nedir?', 'Çok küçük zaman farklarını ölçebilmek', ['Seyircileri eğlendirmek', 'Sporcuları korkutmak', 'Yarışı uzatmak']],
        ['Başlangıç takozundaki algılayıcılar neyi fark eder?', 'Sporcunun işaretten önce çıkmasını', ['Sporcunun boyunu', 'Havanın sıcaklığını', 'Seyirci sayısını']],
        ['Yüzücülerin mayoları hangi amaçla tasarlanır?', 'Suyun sürtünmesini azaltmak için', ['Daha ağır olmak için', 'Renkli görünmek için', 'Suyu ısıtmak için']],
        ['Son paragrafta vurgulanan düşünce hangisidir?', 'Başarı için emek ve çalışma şarttır.', ['Teknoloji her şeyi çözer.', 'Madalya kazanmak kolaydır.', 'Antrenman gereksizdir.']],
        ['Metinde hangi soruya cevap bulunamaz?', 'İlk olimpiyatlar hangi yıl yapılmıştır?', ['Takozlar ne işe yarar?', 'Koşu ayakkabıları nasıl yapılır?', 'Zaman ölçerler neden kullanılır?']]],
      sozcuk: ['sürtünme', ['iki yüzeyin birbirine değerken hareketi zorlaştırması', 'hızlı koşma', 'suya atlama', 'madalya töreni']],
      sira: ['Sporcu ayağını takoza yerleştirir.', 'Başlama işareti verilir.', 'Sporcu koşar.', 'Zaman ölçer bitişi kaydeder.', 'Sonuç açıklanır.'] }),
    'hafta-16': W(16, 4, 'Hayata Varım', 'Bilim ve teknoloji · Teknoloji ve engelsiz yaşam', { baslik: 'Selin\'in Yeni Bacağı',
      metin: ['Selin, küçükken geçirdiği bir kazada bir bacağını kaybetmişti. Okula tekerlekli sandalyeyle geliyordu ama en büyük hayali koşmaktı.',
        'Bir gün doktoru ona yeni bir haber verdi: Selin için özel bir protez bacak yapılacaktı. Mühendisler Selin\'in ölçülerini aldı, bilgisayarda bir tasarım hazırladı. Protez hafif ama dayanıklı bir malzemeden üretildi.',
        'İlk günler Selin protezle yürümekte zorlandı. Fizyoterapistiyle her gün çalıştı. Bazen düştü, bazen ağladı ama hiç vazgeçmedi.',
        'Aylar sonra okulun spor şenliğinde Selin de yarışa katıldı. Birinci olmadı ama bitiş çizgisini geçtiğinde bütün okul onu alkışladı. Selin gülümseyerek “Ben buradayım, hayata varım!” diye bağırdı.'],
      sorular: [['Selin\'in en büyük hayali nedir?', 'Koşmak', ['Doktor olmak', 'Resim yapmak', 'Yüzmek']],
        ['Protezin yapımında kimler görev almıştır?', 'Mühendisler', ['Öğretmenler', 'Aşçılar', 'Çiftçiler']],
        ['Selin\'in davranışlarından hangi özelliği anlaşılır?', 'Kararlılık', ['Tembellik', 'Bencillik', 'Kıskançlık']],
        ['“Hayata varım!” sözüyle Selin ne anlatmak istemiştir?', 'Engellerine rağmen hayatın içinde olduğunu', ['Yarışı kazandığını', 'Okuldan ayrılacağını', 'Çok yorulduğunu']],
        ['Metinden teknoloji ile ilgili hangi sonuca ulaşılır?', 'Teknoloji insanların hayatını kolaylaştırabilir.', ['Teknoloji yalnız oyun içindir.', 'Protezler hiç işe yaramaz.', 'Bilgisayarlar spor yapar.']]],
      sozcuk: ['protez', ['eksik bir organın yerine takılan yapay parça', 'tekerlekli sandalye', 'spor ayakkabısı', 'hastane yatağı']],
      sira: ['Selin bir kaza geçirdi.', 'Doktor protez haberini verdi.', 'Mühendisler protezi tasarladı.', 'Selin her gün çalıştı.', 'Spor şenliğinde yarıştı.'] }),
    'hafta-17': W(17, 4, 'Otomobil Uçar Gider', 'Bilim ve teknoloji · Hayal gücü, tahmin', { baslik: 'Defne\'nin Tasarımı',
      metin: ['Okulda “Geleceğin Taşıtları” yarışması düzenlendi. Defne günlerce düşündü. Şehirdeki trafik sıkışıklığı, egzoz dumanı ve korna sesleri aklından çıkmıyordu.',
        'Sonunda bir tasarım çizdi: güneş enerjisiyle çalışan, sessiz, küçük bir uçan araç. Aracın kanatlarında güneş panelleri vardı. Trafik ışıkları yerine havada görünmeyen yollar olacaktı.',
        'Defne tasarımını sınıfa sunduğunda arkadaşları sorular sordu: “Yağmurlu havada nasıl uçacak?” “Gece nasıl şarj olacak?” Defne her soruyu not aldı ve tasarımını geliştirdi. Araca bir pil ekledi, kanatlara su tutmayan bir kaplama düşündü.',
        'Yarışmada Defne birinci olmadı ama jüri onun soruları dinleyip tasarımını geliştirmesini çok beğendi. Jüri üyesi bir mühendis, “Gerçek mucitler eleştirilerden öğrenir.” dedi.'],
      sorular: [['Defne\'yi böyle bir tasarım yapmaya yönelten sorunlar nelerdir?', 'Trafik, egzoz dumanı ve gürültü', ['Uçak biletlerinin pahalı olması', 'Okulun uzak olması', 'Yağmurlu havalar']],
        ['Defne arkadaşlarının sorularından sonra ne yapmıştır?', 'Tasarımını geliştirmiştir.', ['Yarışmadan çekilmiştir.', 'Arkadaşlarına kızmıştır.', 'Tasarımını yırtmıştır.']],
        ['Mühendisin sözünden çıkarılacak ders hangisidir?', 'Eleştiriler bizi geliştirebilir.', ['Mucitler hep birinci olur.', 'Soru sormak kabalıktır.', 'Tasarımlar değiştirilmemelidir.']],
        ['Defne\'nin aracının enerji kaynağı nedir?', 'Güneş enerjisi', ['Benzin', 'Kömür', 'Rüzgâr']],
        ['Metne en uygun başlık hangisidir?', 'Eleştiriden Doğan Tasarım', ['Trafik Kuralları', 'Yağmurlu Bir Gün', 'Okul Gezisi']]],
      sozcuk: ['jüri', ['yarışmada değerlendirme yapan kurul', 'yarışma ödülü', 'seyirci', 'araç parçası']],
      sira: ['Okulda yarışma duyuruldu.', 'Defne tasarımını çizdi.', 'Arkadaşları sorular sordu.', 'Defne tasarımını geliştirdi.', 'Jüri tasarımı değerlendirdi.'] }),
    'hafta-18': W(18, 4, 'Robotların Ustası', 'Bilim ve teknoloji · Biyografi, bilgilendirici metin', { baslik: 'El Cezerî',
      metin: ['El Cezerî, yaklaşık sekiz yüz yıl önce Cizre\'de yaşamış büyük bir bilim insanı ve mühendistir. Kendi kendine çalışan makineler tasarladığı için “robotların ve sibernetiğin öncüsü” olarak anılır.',
        'El Cezerî, makinelerini çizimlerle ve ayrıntılı açıklamalarla bir kitapta anlattı. Bu kitapta su gücüyle çalışan saatler, su pompaları ve otomatik oyuncaklar yer alır.',
        'En ünlü buluşlarından biri “Fil Saati”dir. Bu saatte suyla dolup boşalan bir kap, zamanı ölçer ve her yarım saatte bir küçük figürler hareket ederek ses çıkarırdı.',
        'El Cezerî\'nin çizimleri bugün bile mühendislere ilham veriyor. Onun hayatı, merak ve sabırla çalışmanın yüzyıllar sonra bile değer taşıyabileceğini gösteriyor.'],
      sorular: [['El Cezerî nerede yaşamıştır?', 'Cizre\'de', ['İstanbul\'da', 'Ankara\'da', 'Bursa\'da']],
        ['El Cezerî neden “robotların öncüsü” olarak anılır?', 'Kendi kendine çalışan makineler tasarladığı için', ['Çok kitap okuduğu için', 'Fil yetiştirdiği için', 'Uzun yaşadığı için']],
        ['Fil Saati hangi güçle çalışır?', 'Su gücüyle', ['Elektrikle', 'Pille', 'Rüzgârla']],
        ['Metinden El Cezerî\'nin hangi özelliğine ulaşılamaz?', 'Hangi yemekleri sevdiği', ['Makineler tasarladığı', 'Kitap yazdığı', 'Merakla çalıştığı']],
        ['Metnin türü hangisidir?', 'Biyografi', ['Fabl', 'Masal', 'Anı']]],
      sozcuk: ['ilham', ['yeni bir şey yapmak için akla gelen düşünce', 'eski bir saat', 'su pompası', 'kitap kapağı']],
      sira: ['El Cezerî Cizre\'de yaşadı.', 'Makineler tasarladı.', 'Makinelerini bir kitapta anlattı.', 'Fil Saati\'ni yaptı.', 'Çizimleri bugün ilham veriyor.'] }),
    'hafta-19': W(19, 5, 'Alo! Kayın Ağacı mı?', 'Doğa ve evren · Kişileştirme, hikâye unsurları', { baslik: 'Ormandan Gelen Telefon',
      metin: ['Bir gece Ömer\'in telefonu çaldı. Ekranda “Kayın Ağacı” yazıyordu. Ömer şaşkınlıkla telefonu açtı. Derinden gelen bir ses, “Merhaba Ömer, ben ormandaki yaşlı kayın ağacıyım.” dedi.',
        'Kayın ağacı dertliydi: “Geçen hafta ormana piknik için gelenler çöplerini bırakıp gitti. Plastik şişeler köklerimin dibinde duruyor. Bir sincap bir poşete sıkıştı, zor kurtuldu.”',
        'Ömer ertesi gün arkadaşlarını topladı. Eldivenler ve çöp torbalarıyla ormana gittiler. Kayın ağacının çevresini tertemiz yaptılar. Ormanın girişine de “Doğa sizin çöp kutunuz değil!” yazan bir tabela astılar.',
        'O gece Ömer\'in telefonu yine çaldı. Kayın ağacı bu kez gülüyordu: “Teşekkür ederim Ömer. Sincap da sana selam söylüyor!” Ömer gözlerini açtığında sabah olmuştu. Rüya mıydı, bilmiyordu ama tabela hâlâ ormanın girişindeydi.'],
      sorular: [['Hikâyede insan gibi konuşan varlık hangisidir?', 'Kayın ağacı', ['Ömer', 'Tabela', 'Orman bekçisi']],
        ['Kayın ağacının dertli olmasının nedeni nedir?', 'Ormana çöp bırakılması', ['Yapraklarının dökülmesi', 'Yağmur yağmaması', 'Telefonunun bozulması']],
        ['Ömer ve arkadaşları ormanda ne yapmıştır?', 'Çöpleri toplayıp tabela asmıştır.', ['Piknik yapıp gitmiştir.', 'Ağaç kesmiştir.', 'Sincap yakalamıştır.']],
        ['Hikâyenin sonunda “Rüya mıydı, bilmiyordu” cümlesi neyi gösterir?', 'Olayların gerçek mi düş mü olduğunun belirsiz olduğunu', ['Ömer\'in uyuyamadığını', 'Telefonun bozulduğunu', 'Tabelanın kaybolduğunu']],
        ['Hikâyenin iletisi hangisidir?', 'Doğayı korumak hepimizin görevidir.', ['Geceleri telefon açılmamalıdır.', 'Sincaplar poşetle oynar.', 'Ormana gitmek tehlikelidir.']]],
      sozcuk: ['dertli', ['üzüntüsü, sıkıntısı olan', 'çok neşeli', 'uykulu', 'aç']],
      sira: ['Ömer\'in telefonu çaldı.', 'Kayın ağacı derdini anlattı.', 'Ömer arkadaşlarını topladı.', 'Ormanı temizlediler.', 'Kayın ağacı teşekkür etti.'] }),
    'hafta-20': W(20, 5, 'Güneş Nasıl Çalışır?', 'Doğa ve evren · Bilgilendirici metin, sayısal bilgi', { baslik: 'Gökyüzünün Fırını',
      metin: ['Güneş, gökyüzünde gördüğümüz en parlak yıldızdır. Diğer yıldızlar da aslında birer güneştir; ama bize çok uzak oldukları için küçük noktalar gibi görünürler.',
        'Güneş çok sıcak gazlardan oluşan kocaman bir küredir. Çapı Dünya\'nın çapından yaklaşık 109 kat büyüktür. İç kısmındaki sıcaklık milyonlarca dereceye ulaşır.',
        'Güneş\'ten çıkan ışık, Dünya\'ya yaklaşık 8 dakikada ulaşır. Yani gökyüzüne baktığımızda Güneş\'i 8 dakika önceki hâliyle görürüz. Bu ışık bitkilerin büyümesini sağlar, Dünya\'yı ısıtır ve hayatı mümkün kılar.',
        'Güneş\'e asla çıplak gözle ya da dürbünle bakmamalıyız; gözlerimize kalıcı zarar verebilir. Güneş tutulmasını izlerken bile özel gözlükler kullanmalıyız.'],
      sorular: [['Diğer yıldızların küçük noktalar gibi görünmesinin nedeni nedir?', 'Bize çok uzak olmaları', ['Çok küçük olmaları', 'Işık vermemeleri', 'Gündüz görünmemeleri']],
        ['Güneş ışığı Dünya\'ya yaklaşık ne kadar sürede ulaşır?', '8 dakikada', ['8 saatte', '8 günde', '8 saniyede']],
        ['Metne göre hangisi Güneş ışığının yararlarından biri değildir?', 'Gece karanlığını oluşturması', ['Bitkilerin büyümesini sağlaması', 'Dünya\'yı ısıtması', 'Hayatı mümkün kılması']],
        ['Son paragrafta okura hangi uyarı yapılmaktadır?', 'Güneş\'e çıplak gözle bakmamalıyız.', ['Güneş tutulmasını izlememeliyiz.', 'Dürbün kullanmalıyız.', 'Güneşte çok kalmalıyız.']],
        ['Güneş\'in çapı ile ilgili hangisi doğrudur?', 'Dünya\'nın çapından yaklaşık 109 kat büyüktür.', ['Dünya\'nın çapına eşittir.', 'Dünya\'nın çapından küçüktür.', 'Dünya\'nın çapının iki katıdır.']]],
      sozcuk: ['kalıcı', ['uzun süre geçmeyen, sürekli', 'kısa süren', 'eğlenceli', 'hafif']],
      sira: ['Güneş\'te ışık oluşur.', 'Işık uzayda yol alır.', 'Yaklaşık 8 dakika sonra Dünya\'ya ulaşır.', 'Bitkiler bu ışıkla büyür.'] }),
    'hafta-21': W(21, 5, 'Orman Dostları', 'Doğa ve evren · Ağaçlandırma, yönerge', { baslik: 'Bir Fidan Nasıl Dikilir?',
      metin: ['Kasım ayı, fidan dikmek için en uygun zamanlardan biridir. Bu dönemde toprak nemlidir ve fidanlar kök salmak için yeterli zaman bulur.',
        'Fidan dikmek için önce uygun bir yer seçilir. Fidanın kökünden biraz daha geniş ve derin bir çukur kazılır. Fidan çukura dik olarak yerleştirilir; kökleri kıvrılmamalıdır.',
        'Ardından çukur toprakla doldurulur ve toprak hafifçe bastırılır. Fidanın yanına rüzgârda devrilmemesi için bir destek çubuğu çakılır. Son olarak fidan bolca sulanır. Bu ilk suya “can suyu” denir.',
        'Bir ağaç büyüdüğünde bize temiz hava, gölge ve meyve verir; kuşlara ve böceklere yuva olur. Bu yüzden her yıl en az bir fidan dikmek, geleceğe bırakılan en güzel armağandır.'],
      sorular: [['Fidan dikerken ilk yapılması gereken nedir?', 'Uygun bir yer seçmek', ['Fidanı sulamak', 'Destek çubuğu çakmak', 'Toprağı bastırmak']],
        ['Destek çubuğunun görevi nedir?', 'Fidanın rüzgârda devrilmesini önlemek', ['Fidanı sulamak', 'Kuşları korkutmak', 'Toprağı ısıtmak']],
        ['“Can suyu” nedir?', 'Fidan dikildikten sonra verilen ilk su', ['Yağmur suyu', 'Ağacın meyvesi', 'Çukurdaki toprak']],
        ['Metinde ağaçların hangi yararından söz edilmemiştir?', 'Kâğıt yapımında kullanılması', ['Temiz hava vermesi', 'Gölge vermesi', 'Canlılara yuva olması']],
        ['Metin hangi amaçla yazılmıştır?', 'Fidan dikmeyi adım adım anlatmak', ['Bir masal anlatmak', 'Bir şiir okutmak', 'Bir fıkra anlatmak']]],
      sozcuk: ['kök salmak', ['köklerin toprağa yayılıp tutunması', 'yaprak dökmek', 'meyve vermek', 'kurumak']],
      sira: ['Uygun bir yer seçilir.', 'Çukur kazılır.', 'Fidan çukura yerleştirilir.', 'Destek çubuğu çakılır.', 'Can suyu verilir.'] }),
    'hafta-22': W(22, 5, 'İklim Değişikliği', 'Doğa ve evren · Bilgilendirici metin, sebep-sonuç', { baslik: 'Dünyamızın Ateşi',
      metin: ['Son yıllarda yazlar daha sıcak geçiyor, bazı yerlerde kuraklık, bazı yerlerde de seller yaşanıyor. Bilim insanları bu değişikliklerin iklim değişikliğiyle ilgili olduğunu söylüyor.',
        'İklim, bir yerde uzun yıllar boyunca görülen hava koşullarıdır. Fabrikalardan, araçlardan ve yakılan yakıtlardan çıkan bazı gazlar atmosferde birikir. Bu gazlar Güneş\'ten gelen ısının bir kısmını hapseder ve Dünya yavaş yavaş ısınır.',
        'Isınma sonucunda buzullar erir, deniz seviyesi yükselir, bazı canlıların yaşam alanları daralır.',
        'Hepimiz bu soruna karşı bir şeyler yapabiliriz: Kısa mesafelerde yürüyebilir ya da bisiklet kullanabiliriz. Gereksiz ışıkları kapatabilir, ağaç dikebilir, atıklarımızı geri dönüşüme gönderebiliriz.'],
      sorular: [['Metne göre Dünya\'nın ısınmasının nedeni nedir?', 'Atmosferde biriken gazların ısıyı hapsetmesi', ['Güneş\'in Dünya\'ya yaklaşması', 'Ay\'ın büyümesi', 'Yağmurların artması']],
        ['İklim nedir?', 'Bir yerde uzun yıllar görülen hava koşulları', ['Bir günlük hava durumu', 'Yalnız yağmurlu günler', 'Bir şehrin nüfusu']],
        ['Hangisi ısınmanın sonuçlarından biri değildir?', 'Buzulların büyümesi', ['Deniz seviyesinin yükselmesi', 'Yaşam alanlarının daralması', 'Kuraklık yaşanması']],
        ['Son paragrafta okurlardan ne istenmektedir?', 'Günlük yaşamda iklimi korumaya katkı sağlamaları', ['Daha çok araç kullanmaları', 'Işıkları açık bırakmaları', 'Ağaçları kesmeleri']],
        ['Metnin başlığındaki “ateş” sözcüğü neyi anlatmaktadır?', 'Dünya\'nın ısınmasını', ['Orman yangınlarını', 'Ocaktaki ateşi', 'Güneş\'in rengini']]],
      sozcuk: ['hapsetmek', ['bir yere kapatıp çıkmasına izin vermemek', 'serbest bırakmak', 'temizlemek', 'ölçmek']],
      sira: ['Yakıtlar yakılır.', 'Gazlar atmosferde birikir.', 'Isı hapsedilir.', 'Dünya ısınır.', 'Buzullar erir.'] }),
    'hafta-23': W(23, 6, 'Anadolu Bacıları', 'Millî kültürümüz · Bilgilendirici metin, tarih', { baslik: 'Dokumacı Bacılar',
      metin: ['Yaklaşık yedi yüz yıl önce Anadolu\'da kadınlar bir araya gelerek bir birlik kurdu. Bu birliğe “Anadolu Bacıları” denir. Birliğin üyeleri dokumacılık, keçecilik ve nakış gibi el sanatlarıyla uğraşırdı.',
        'Bacılar yalnız üretim yapmazdı; genç kızlara meslek öğretir, yoksul ailelere yardım eder, yolculara konaklayacak yer sağlardı. Böylece hem aile ekonomisine hem de topluma katkıda bulunurlardı.',
        'Birliğin üyeleri dürüst ticaret yapmaya, yaptıkları işi en iyi şekilde yapmaya ve yardımlaşmaya önem verirdi. Bu değerler, aynı dönemde erkeklerin kurduğu Ahilik teşkilatının değerleriyle benzerdi.',
        'Bugün Anadolu\'nun birçok yerinde kadınların kurduğu kooperatifler, bu köklü geleneği yaşatmaya devam ediyor.'],
      sorular: [['Anadolu Bacıları hangi işlerle uğraşırdı?', 'Dokumacılık ve el sanatları', ['Gemicilik', 'Madencilik', 'Demircilik']],
        ['Metne göre bacılar topluma nasıl katkı sağlamıştır?', 'Meslek öğretip yardımlaşarak', ['Savaşa katılarak', 'Kitap yazarak', 'Saray yaptırarak']],
        ['Anadolu Bacıları\'nın değerleri hangi teşkilatın değerlerine benzer?', 'Ahilik', ['Kızılay', 'Yeşilay', 'İzcilik']],
        ['Son paragrafta hangi düşünce vurgulanmaktadır?', 'Bu gelenek bugün de yaşatılmaktadır.', ['Birlik tamamen unutulmuştur.', 'Kooperatifler zararlıdır.', 'El sanatları yok olmuştur.']],
        ['Metnin konusu hangisidir?', 'Anadolu\'da kadınların kurduğu tarihî bir birlik', ['Anadolu\'nun coğrafyası', 'Bir dokuma tezgâhının yapımı', 'Yolcuların tatil anıları']]],
      sozcuk: ['kooperatif', ['ortak çıkar için birleşen kişilerin kurduğu kuruluş', 'büyük bir pazar', 'eski bir saray', 'el yazması kitap']],
      sira: ['Kadınlar bir araya geldi.', 'Anadolu Bacıları birliği kuruldu.', 'Genç kızlara meslek öğretildi.', 'Topluma yardım edildi.', 'Gelenek kooperatiflerle sürdü.'] }),
    'hafta-24': W(24, 6, 'Kapalıçarşı', 'Millî kültürümüz · Bilgilendirici metin, gezi', { baslik: 'Dünyanın İlk Alışveriş Merkezi',
      metin: ['İstanbul\'un en eski ve en büyük çarşılarından biri Kapalıçarşı\'dır. Çarşının yapımına Fatih Sultan Mehmet döneminde, beş yüz yılı aşkın süre önce başlanmıştır.',
        'Kapalıçarşı\'nın üstü kubbelerle örtülüdür. Bu yüzden yağmurda da karda da insanlar rahatça alışveriş yapabilir. Çarşıda altmıştan fazla sokak ve yaklaşık dört bin dükkân bulunur.',
        'Eskiden her sokakta aynı mesleği yapan esnaf bulunurdu: kuyumcular bir sokakta, halıcılar başka bir sokakta, terziler bir başkasında. Sokakların adları bugün de bu meslekleri hatırlatır.',
        'Kapalıçarşı her gün binlerce yerli ve yabancı ziyaretçiyi ağırlar. Burası yalnızca bir alışveriş yeri değil, yüzyıllardır yaşayan canlı bir müzedir.'],
      sorular: [['Kapalıçarşı\'nın yapımına hangi dönemde başlanmıştır?', 'Fatih Sultan Mehmet döneminde', ['Cumhuriyet döneminde', 'Kurtuluş Savaşı\'nda', 'Geçen yüzyılda']],
        ['Çarşının üstünün kubbelerle örtülü olmasının yararı nedir?', 'Her havada alışveriş yapılabilmesi', ['Daha çok ışık girmesi', 'Kuşların içeri girmesi', 'Dükkânların küçülmesi']],
        ['Sokakların adları neyi hatırlatır?', 'Eskiden orada yapılan meslekleri', ['Ünlü kişilerin adlarını', 'Şehirlerin adlarını', 'Ağaç türlerini']],
        ['Yazar Kapalıçarşı\'yı neden “canlı bir müze” olarak nitelendirmiştir?', 'Tarihî bir yer olduğu hâlde bugün de kullanıldığı için', ['İçinde müze bulunduğu için', 'Hayvanlar yaşadığı için', 'Çok sessiz olduğu için']],
        ['Metinde hangi soruya cevap yoktur?', 'Çarşıda en çok hangi ürün satılır?', ['Çarşıda kaç sokak vardır?', 'Çarşının üstü neyle örtülüdür?', 'Çarşı hangi şehirdedir?']]],
      sozcuk: ['esnaf', ['dükkânda alım satım ya da zanaat yapanlar', 'müze rehberi', 'yabancı turist', 'çarşının kubbesi']],
      sira: ['Çarşının yapımına başlandı.', 'Üstü kubbelerle örtüldü.', 'Her sokağa bir meslek yerleşti.', 'Çarşı büyüdü.', 'Bugün ziyaretçileri ağırlıyor.'] }),
    'hafta-25': W(25, 6, 'Yatıya Misafir', 'Millî kültürümüz · Misafirlik geleneği, hikâye', { baslik: 'Fıldır\'ın Misafirleri',
      metin: ['Fıldır, Nehir\'lerin evinde yaşayan meraklı bir kediydi. Bir akşam kapı çaldı ve Anneanne, köyden yatıya misafir olarak geldi. Fıldır hemen kapıya koştu.',
        'Nehir\'in annesi misafir için en güzel yatağı hazırladı. Babası anneannenin bavulunu taşıdı. Nehir de çay demledi, anneannesine en sevdiği bardakla ikram etti. Fıldır bütün bunları koltuğun üstünden izliyordu.',
        'Akşam yemeğinden sonra anneanne çantasından ev yapımı tarhana, ceviz ve el örgüsü patikler çıkardı. “Eli boş gelmek olmaz.” dedi gülümseyerek. Nehir patikleri hemen giydi.',
        'Gece herkes uyurken Fıldır, anneannenin ayakucunda kıvrılıp yattı. Sabah anneanne “Bu evde kediler bile misafir ağırlamayı biliyor!” dedi ve herkes güldü.'],
      sorular: [['Anneanne neden Nehir\'lere gelmiştir?', 'Yatıya misafir olarak', ['Kedi almak için', 'Doktora gitmek için', 'Taşınmak için']],
        ['Ailenin misafire davranışı hangi geleneği yansıtır?', 'Misafirperverlik', ['Bayram ziyareti', 'Sünnet düğünü', 'Kına gecesi']],
        ['“Eli boş gelmek olmaz.” sözüyle anneanne ne anlatmak istemiştir?', 'Ziyarete giderken hediye götürülür.', ['Ellerimizi yıkamalıyız.', 'Çanta taşımak zordur.', 'Misafirlik yapılmamalıdır.']],
        ['Metindeki mizahi (güldürücü) unsur hangisidir?', 'Kedinin de misafir ağırlaması', ['Çay demlenmesi', 'Bavul taşınması', 'Yatağın hazırlanması']],
        ['Metnin ana fikri hangisidir?', 'Misafirlerimizi sevgiyle ağırlamalıyız.', ['Kediler çay sever.', 'Anneanneler köyde yaşamalıdır.', 'Ceviz sağlıklıdır.']]],
      sozcuk: ['ikram etmek', ['misafire yiyecek içecek sunmak', 'ödünç vermek', 'satın almak', 'saklamak']],
      sira: ['Anneanne yatıya geldi.', 'Annesi yatak hazırladı.', 'Nehir çay ikram etti.', 'Anneanne hediyelerini çıkardı.', 'Fıldır ayakucunda uyudu.'] }),
    'hafta-26': W(26, 6, 'Türk Okçuluğu', 'Millî kültürümüz · Geleneksel sporlar, bilgilendirici metin', { baslik: 'Yay ve Ok',
      metin: ['Okçuluk, Türklerin binlerce yıllık geleneksel sporlarından biridir. Eski Türkler okçuluğu hem avlanmak hem de kendilerini korumak için kullanırdı.',
        'Geleneksel Türk yayı küçük ama çok güçlüdür. Ağaç, boynuz ve hayvan sinirinin birleştirilmesiyle yapılır. Bu malzemeler yaya hem esneklik hem de dayanıklılık kazandırır. Bir yayın yapımı aylarca sürebilir.',
        'Osmanlı döneminde İstanbul\'da Okmeydanı adında okçuların yarıştığı geniş bir alan vardı. Burada en uzağa atış yapan okçuların rekorları taşlara yazılırdı. Bu taşlara “menzil taşı” denir.',
        'Okçuluk sabır, dikkat ve denge ister. Bugün birçok şehirde geleneksel okçuluk kulüpleri bulunuyor ve çocuklar da bu sporu öğrenebiliyor.'],
      sorular: [['Eski Türkler okçuluğu ne amaçla kullanırdı?', 'Avlanmak ve kendilerini korumak için', ['Müzik yapmak için', 'Ev yapmak için', 'Yemek pişirmek için']],
        ['Geleneksel Türk yayının yapımında hangisi kullanılmaz?', 'Plastik', ['Ağaç', 'Boynuz', 'Hayvan siniri']],
        ['“Menzil taşı” nedir?', 'Rekor atışların yazıldığı taş', ['Okun ucu', 'Yay yapımında kullanılan taş', 'Okçuların oturduğu taş']],
        ['Hangisi okçuluğun gerektirdiği özelliklerden biri değildir?', 'Hız için koşmak', ['Sabır', 'Dikkat', 'Denge']],
        ['Metne göre okçuluk bugün nasıl yaşatılmaktadır?', 'Okçuluk kulüpleriyle', ['Okmeydanı\'nda savaşlarla', 'Avcılıkla', 'Yalnız müzelerde']]],
      sozcuk: ['dayanıklılık', ['kolay bozulmama, sağlamlık', 'hafiflik', 'renklilik', 'yumuşaklık']],
      sira: ['Ağaç, boynuz ve sinir hazırlanır.', 'Malzemeler birleştirilir.', 'Yay aylarca kurutulur.', 'Okçu atış yapar.', 'Rekor menzil taşına yazılır.'] }),
    'hafta-27': W(27, 6, 'Keloğlan\'ın Bilmecesi', 'Millî kültürümüz · Halk edebiyatı, masal', { baslik: 'Keloğlan ve Üç Soru',
      metin: ['Evvel zaman içinde, bir köyde Keloğlan adında akıllı bir genç yaşardı. Bir gün ülkenin padişahı, kim üç sorusunu bilirse ona bir kese altın vereceğini duyurdu.',
        'Saraya pek çok bilgin geldi ama hiçbiri soruları bilemedi. Sıra Keloğlan\'a gelince padişah sordu: “Dünyada en hızlı giden nedir?” Keloğlan güldü: “Düşüncedir padişahım, göz açıp kapayıncaya kadar her yere varır.”',
        'Padişah ikinci soruyu sordu: “En tatlı şey nedir?” Keloğlan “Uykudur, padişahım. Yorulan insanın en çok aradığı odur.” dedi. Üçüncü soru zordu: “En değerli hazine nedir?” Keloğlan biraz düşündü ve “Dosttur padişahım. Altın tükenir, iyi dost tükenmez.” dedi.',
        'Padişah cevaplardan çok memnun kaldı. Keloğlan altınları alıp köyüne döndü ve köyün yıkılan köprüsünü yeniden yaptırdı. Gökten üç elma düştü: biri anlatana, biri dinleyene, biri de okuyana.'],
      sorular: [['Metnin türü hangisidir?', 'Masal', ['Fabl', 'Biyografi', 'Haber']],
        ['Keloğlan\'a göre dünyada en hızlı giden nedir?', 'Düşünce', ['At', 'Rüzgâr', 'Kuş']],
        ['Keloğlan\'ın üçüncü cevabından çıkarılan ders hangisidir?', 'İyi dostluklar paradan değerlidir.', ['Altın en büyük hazinedir.', 'Uyku her şeyden önemlidir.', 'Padişahlar her şeyi bilir.']],
        ['Keloğlan altınlarla ne yapmıştır?', 'Köyün köprüsünü yaptırmıştır.', ['Saray yaptırmıştır.', 'Altınları saklamıştır.', 'Şehre taşınmıştır.']],
        ['“Evvel zaman içinde” ve “Gökten üç elma düştü” ifadeleri masalın hangi bölümleridir?', 'Giriş ve bitiş kalıpları', ['Olayın en heyecanlı yerleri', 'Kahramanın sözleri', 'Padişahın soruları']]],
      sozcuk: ['bilgin', ['çok bilgili kişi', 'saray bekçisi', 'köylü', 'tüccar']],
      sira: ['Padişah yarışma duyurdu.', 'Bilginler soruları bilemedi.', 'Keloğlan soruları cevapladı.', 'Padişah altınları verdi.', 'Keloğlan köprü yaptırdı.'] }),
    'hafta-28': W(28, 7, 'Annem Diyor ki', 'Çocuk dünyası · Öğüt, konuşma', { baslik: 'Annemin Sözleri',
      metin: ['Annem her sabah okula giderken bana bir şey söyler. Bazen “Dikkatli yürü.” der, bazen “Bugün yeni bir şey öğren.” Ben de bu sözleri küçük bir deftere yazarım.',
        'Bir gün annem “Yanlış yaptığında özür dilemekten çekinme.” dedi. O gün teneffüste yanlışlıkla arkadaşım Su\'nun kalemini kırdım. Önce saklamak istedim, sonra annemin sözü aklıma geldi. Su\'ya gidip özür diledim ve kendi kalemimi ona verdim. Su gülümsedi ve bana sarıldı.',
        'Başka bir gün annem “Kitapsız bir gün, pencereden bakmadan geçen bir gün gibidir.” dedi. O akşam televizyonu kapatıp bir kitap okudum. Kitaptaki çocukla birlikte uzak diyarları gezdim.',
        'Defterim artık sayfa sayfa dolu. Bir gün ben de büyüyünce bu defteri çocuğuma vereceğim. Belki o da kendi sözlerini ekler.'],
      sorular: [['Anlatıcı annesinin sözlerini nereye yazmaktadır?', 'Küçük bir deftere', ['Kara tahtaya', 'Telefonuna', 'Duvara']],
        ['Anlatıcı kalemi kırdıktan sonra ne yapmıştır?', 'Özür dileyip kendi kalemini vermiştir.', ['Kalemi saklamıştır.', 'Öğretmene şikâyet etmiştir.', 'Eve kaçmıştır.']],
        ['“Kitapsız bir gün, pencereden bakmadan geçen bir gün gibidir.” sözüyle anlatılmak istenen nedir?', 'Kitaplar bize yeni dünyalar gösterir.', ['Pencereler temiz tutulmalıdır.', 'Kitaplar pencerede okunmalıdır.', 'Gündüzleri dışarı bakmalıyız.']],
        ['Metin hangi bakış açısıyla yazılmıştır?', 'Birinci kişi (ben) ağzından', ['Annenin ağzından', 'Su\'nun ağzından', 'Öğretmenin ağzından']],
        ['Metnin konusu hangisidir?', 'Bir çocuğun annesinin öğütlerinden öğrendikleri', ['Kırılan kalemin tamiri', 'Televizyon programları', 'Uzak diyarlara yolculuk']]],
      sozcuk: ['çekinmek', ['bir şeyi yapmaktan utanmak, kaçınmak', 'koşmak', 'gülmek', 'yazmak']],
      sira: ['Annem özür dilemekten söz etti.', 'Su\'nun kalemini kırdım.', 'Özür diledim.', 'Annem kitaplardan söz etti.', 'Televizyonu kapatıp kitap okudum.'] }),
    'hafta-29': W(29, 7, 'Güzel Anıları Biriktirmek', 'Çocuk dünyası · Anı, duygular', { baslik: 'Anı Kutusu',
      metin: ['Dedemin evinde tozlu bir teneke kutu vardı. Bir gün dedem kutuyu açtı. İçinden eski bir bilet, kurumuş bir papatya, sararmış fotoğraflar ve küçük bir taş çıktı.',
        'Dedem her birini tek tek anlattı. Bilet, ilk kez trene bindiği günün hatırasıydı. Papatyayı ninem ona ilk tanıştıkları gün vermişti. Taşı ise çocukken yüzdüğü dereden almıştı.',
        'O gün ben de kendi anı kutumu hazırlamaya karar verdim. İçine 1. sınıfta yazdığım ilk cümleyi, deniz kenarında bulduğum bir deniz kabuğunu ve doğum günü kartlarımı koydum.',
        'Anılar, zamanla unutulmaya yüz tutan günlerimizi saklar. Kutuyu her açtığımda o günlerin sesi, kokusu ve neşesi yeniden aklıma geliyor.'],
      sorular: [['Dedenin kutusundaki bilet neyin hatırasıdır?', 'İlk kez trene bindiği günün', ['Bir futbol maçının', 'Bir sinema filminin', 'Okul gezisinin']],
        ['Hangisi anlatıcının kendi anı kutusuna koyduğu eşyalardan biri değildir?', 'Kurumuş papatya', ['İlk yazdığı cümle', 'Deniz kabuğu', 'Doğum günü kartları']],
        ['Metnin türü hangisidir?', 'Anı', ['Masal', 'Fabl', 'Bilgilendirici metin']],
        ['“Unutulmaya yüz tutmak” deyiminin anlamı nedir?', 'Unutulmaya başlamak', ['Hiç unutulmamak', 'Yüzü görmek', 'Bir şeyi saklamak']],
        ['Metnin ana fikri hangisidir?', 'Anıları saklamak geçmişimizi canlı tutar.', ['Teneke kutular eskidir.', 'Taşlar dereden alınmamalıdır.', 'Tren yolculuğu pahalıdır.']]],
      sozcuk: ['hatıra', ['geçmişte yaşanan bir olayı hatırlatan şey', 'yeni bir oyuncak', 'tren bileti satıcısı', 'yemek tarifi']],
      sira: ['Dedem kutuyu açtı.', 'Eşyaların hikâyesini anlattı.', 'Anı kutusu hazırlamaya karar verdim.', 'Kutuma eşyalarımı koydum.', 'Kutuyu açtıkça anılarımı hatırlıyorum.'] }),
    'hafta-30': W(30, 7, 'Arkadaşım 23 Nisan', 'Çocuk dünyası · Millî bayram, yazma', { baslik: 'Dünya Çocuklarının Bayramı',
      metin: ['23 Nisan 1920\'de Ankara\'da Türkiye Büyük Millet Meclisi açıldı. Atatürk, bu önemli günü çocuklara armağan etti. Bu yüzden 23 Nisan, Ulusal Egemenlik ve Çocuk Bayramı olarak kutlanır.',
        'Bu yıl okulumuzda bayram için hazırlık yaptık. Sınıfımız farklı ülkelerin çocuklarını tanıtan bir pano hazırladı. Her öğrenci bir ülkenin bayrağını çizdi ve o ülkenin çocuk oyunlarını araştırdı.',
        'Bayram günü okul bahçesi rengârenk oldu. Şiirler okundu, halk oyunları oynandı. Bizim sınıf, Japonya\'dan bir ip atlama oyununu ve Brezilya\'dan bir top oyununu herkese öğretti.',
        'Gün sonunda öğretmenimiz şöyle dedi: “23 Nisan, dünyadaki bütün çocukların kardeş olduğunu hatırlatır.” O gün anladım ki dil, renk ya da ülke fark etmeksizin bütün çocuklar oyunda aynı dili konuşur.'],
      sorular: [['23 Nisan 1920\'de hangi olay gerçekleşmiştir?', 'Türkiye Büyük Millet Meclisi açılmıştır.', ['Cumhuriyet ilan edilmiştir.', 'Çanakkale Zaferi kazanılmıştır.', 'İstiklal Marşı kabul edilmiştir.']],
        ['Sınıfın bayram için hazırladığı pano hangi konudaydı?', 'Farklı ülkelerin çocukları', ['Atatürk\'ün hayatı', 'Okulun tarihi', 'Halk oyunları kıyafetleri']],
        ['Öğretmenin sözünden hangi düşünce çıkarılır?', 'Dünya çocukları kardeştir.', ['Yalnız Türk çocukları bayram yapar.', 'Oyunlar ülkeye göre yasaktır.', 'Bayramda ders işlenir.']],
        ['“Bütün çocuklar oyunda aynı dili konuşur.” cümlesiyle anlatılmak istenen nedir?', 'Oyun, farklı çocukları birbirine yaklaştırır.', ['Bütün çocuklar aynı dili bilir.', 'Oyunlarda konuşulmaz.', 'Çocuklar tek bir oyun oynar.']],
        ['Metne göre 23 Nisan\'ı çocuklara kim armağan etmiştir?', 'Atatürk', ['Öğretmenimiz', 'Belediye başkanı', 'Okul müdürü']]],
      sozcuk: ['egemenlik', ['bir ulusun kendi kendini yönetmesi', 'oyun oynamak', 'bayram süsü', 'okul panosu']],
      sira: ['Meclis açıldı.', 'Atatürk bayramı çocuklara armağan etti.', 'Sınıfımız pano hazırladı.', 'Bayramda oyunlar oynandı.', 'Öğretmenimiz konuşma yaptı.'] }),
    'hafta-31': W(31, 7, 'Beştaş', 'Çocuk dünyası · Geleneksel oyunlar, yönerge', { baslik: 'Dedemin Oyunu',
      metin: ['Yağmurlu bir gün evde canımız sıkılıyordu. Dedem cebinden beş küçük, yuvarlak taş çıkardı. “Size çocukluğumun oyununu öğreteyim: Beştaş!” dedi.',
        'Önce taşları yere saçtı. Birini havaya attı, o taş düşmeden yerden bir taş daha aldı ve havadaki taşı yakaladı. Böylece taşları birer birer topladı. Sonra ikişer ikişer, üçer üçer topladı. Taşlardan birini düşüren sırayı arkadaşına bırakıyordu.',
        'İlk denemelerimde taşlar hep elimden kaydı. Dedem “Acele etme. Gözün havadaki taşta olsun.” dedi. Bir saat sonra ben de ikişerli turu geçebiliyordum.',
        'Kardeşim bile tableti bırakıp oyuna katıldı. O gün anladık ki eğlenmek için pahalı oyuncaklara gerek yok. Beş küçük taş, dedemle aramızda kocaman bir köprü kurmuştu.'],
      sorular: [['Dedenin önerdiği oyunun adı nedir?', 'Beştaş', ['Saklambaç', 'Seksek', 'Körebe']],
        ['Oyunda sıra ne zaman arkadaşa geçer?', 'Taşlardan biri düşürülünce', ['Bütün taşlar toplanınca', 'Bir saat geçince', 'Yağmur durunca']],
        ['Dedenin “Gözün havadaki taşta olsun.” sözü hangi amaçla söylenmiştir?', 'Torununa ipucu vermek için', ['Torununu kızdırmak için', 'Oyunu bitirmek için', 'Taşları saklamak için']],
        ['“Beş küçük taş, dedemle aramızda kocaman bir köprü kurmuştu.” cümlesiyle anlatılmak istenen nedir?', 'Oyun, dede ile torunlarını birbirine yakınlaştırmıştır.', ['Taşlarla köprü yapılmıştır.', 'Dede köprü ustasıdır.', 'Oyun çok zordur.']],
        ['Metinden çıkarılabilecek sonuç hangisidir?', 'Geleneksel oyunlar basit araçlarla eğlence sağlar.', ['Tablet en iyi oyuncaktır.', 'Yağmurlu günlerde oyun oynanmaz.', 'Beştaş yalnız büyüklerin oyunudur.']]],
      sozcuk: ['canı sıkılmak', ['yapacak bir şey bulamayıp sıkıntı duymak', 'çok sevinmek', 'acıkmak', 'üşümek']],
      sira: ['Dede taşları çıkardı.', 'Taşları yere saçtı.', 'Birer birer topladı.', 'Anlatıcı denedi ama başaramadı.', 'İkişerli turu geçti.'] }),
    'hafta-32': W(32, 7, 'Uçurtmalar Nasıl Uçar?', 'Çocuk dünyası · Bilgilendirici metin, yönerge', { baslik: 'Rüzgârın Kanatları',
      metin: ['Uçurtma, rüzgârın gücüyle havada kalan hafif bir oyuncaktır. Genellikle ince çıtalardan bir iskelet ve bu iskeleti saran kâğıt ya da kumaştan yapılır.',
        'Rüzgâr uçurtmanın yüzeyine çarptığında onu yukarı doğru iter. Uçurtmanın ipini tutan kişi ipi gergin tutarak uçurtmanın rüzgâra karşı doğru açıyla durmasını sağlar. Uçurtmanın kuyruğu ise dengesini korumasına yardım eder.',
        'Uçurtma uçurmak için açık ve geniş bir alan seçilmelidir. Elektrik tellerinin, ağaçların ve yolların yakınında uçurtma uçurmak tehlikelidir.',
        'Uçurtmalar yalnız oyuncak değildir. Geçmişte bilim insanları hava durumunu incelemek için uçurtmalardan yararlanmıştır. Bugün bile bazı gemiler rüzgâr gücünden yararlanmak için dev uçurtma yelkenleri kullanır.'],
      sorular: [['Metne göre uçurtmayı havada tutan nedir?', 'Rüzgârın gücü', ['Pil gücü', 'Motor', 'Güneş ışığı']],
        ['Uçurtmanın kuyruğunun görevi nedir?', 'Dengesini korumak', ['Süslemek', 'Rüzgârı durdurmak', 'İpi uzatmak']],
        ['Uçurtma uçurmak için en uygun yer hangisidir?', 'Açık ve geniş bir çayır', ['Elektrik tellerinin yanı', 'Kalabalık bir cadde', 'Ağaçlık bir orman']],
        ['Metne göre uçurtmalar oyuncak olmanın dışında ne amaçla kullanılmıştır?', 'Hava durumunu incelemek için', ['Mektup göndermek için', 'Yemek pişirmek için', 'Ev ısıtmak için']],
        ['Metnin türü hangisidir?', 'Bilgilendirici metin', ['Masal', 'Anı', 'Şiir']]],
      sozcuk: ['gergin', ['iyice çekilmiş, gevşek olmayan', 'kopmuş', 'renkli', 'kısa']],
      sira: ['Çıtalarla iskelet yapılır.', 'İskelet kâğıtla kaplanır.', 'Kuyruk ve ip bağlanır.', 'Açık bir alana gidilir.', 'Rüzgârla uçurtma uçurulur.'] }),
    'hafta-33': W(33, 7, 'Sağlığımı Korurum', 'Çocuk dünyası · Sağlıklı yaşam, öneri', { baslik: 'Kerem\'in Bir Günü',
      metin: ['Kerem son günlerde çok yorgundu. Derslerde uykusu geliyor, teneffüste oynamak istemiyordu. Okul hemşiresi Kerem\'e günlük alışkanlıklarını sordu.',
        'Kerem gece geç saatlere kadar tablette oyun oynadığını, sabahları kahvaltı yapmadan okula geldiğini ve suyu çok az içtiğini anlattı. Hemşire gülümsedi: “Vücudumuz bir bitki gibidir; uykuyla, suyla ve iyi besinle büyür.”',
        'Hemşire Kerem\'e bir plan önerdi: Her gece aynı saatte yatmak, ekranı yatmadan bir saat önce kapatmak, kahvaltıyı atlamamak, gün içinde sık sık su içmek ve her gün en az bir saat hareket etmek.',
        'Kerem planı buzdolabının kapağına astı. İki hafta sonra derslerde daha dikkatliydi, teneffüste arkadaşlarıyla koşup oynuyordu. Hemşireye teşekkür etmeye gittiğinde “Bitkim büyüyor!” dedi.'],
      sorular: [['Hangisi Kerem\'in yorgun olmasının nedenlerinden biri değildir?', 'Her gün spor yapması', ['Geç yatması', 'Kahvaltı yapmaması', 'Az su içmesi']],
        ['Hemşire vücudumuzu neye benzetmiştir?', 'Bitkiye', ['Makineye', 'Arabaya', 'Saate']],
        ['Plana göre ekran yatmadan ne kadar önce kapatılmalıdır?', 'Bir saat önce', ['Beş dakika önce', 'On saat önce', 'Hiç kapatılmamalı']],
        ['Kerem\'in “Bitkim büyüyor!” sözü neyi gösterir?', 'Sağlığının ve enerjisinin düzeldiğini', ['Saksıda bitki yetiştirdiğini', 'Boyunun çok uzadığını', 'Hemşireye hediye verdiğini']],
        ['Metnin ana fikri hangisidir?', 'Düzenli uyku, beslenme ve hareket sağlığı korur.', ['Tablet oyunları dinlendiricidir.', 'Okul hemşireleri bitki yetiştirir.', 'Kahvaltı gereksizdir.']]],
      sozcuk: ['alışkanlık', ['sürekli yapıldığı için kolaylaşan davranış', 'tek seferlik iş', 'ilaç', 'ders programı']],
      sira: ['Kerem çok yorgundu.', 'Hemşire alışkanlıklarını sordu.', 'Hemşire bir plan önerdi.', 'Kerem planı buzdolabına astı.', 'Kerem enerjisine kavuştu.'] }),
    'hafta-34': W(34, 8, 'İlk Yardımı Hatırla', 'Sağlık ve spor · Yönerge, ilk yardım', { baslik: 'Telaşa Kapılma!',
      metin: ['Okulda ilk yardım eğitimi vardı. Eğitmen önce en önemli kuralı söyledi: “Telaşa kapılma! Önce kendi güvenliğini sağla, sonra bir büyüğe haber ver ya da 112\'yi ara.”',
        'Sonra yanık için ne yapılacağını anlattı: Yanan bölge en az 10 dakika akan soğuk suyun altında tutulmalıdır. Yanığa buz, diş macunu ya da yoğurt sürülmemelidir; bunlar yarayı kötüleştirebilir.',
        'Burun kanaması için de bir kural vardı: Baş hafifçe öne eğilmeli ve burnun yumuşak kısmı yaklaşık 10 dakika sıkılmalıdır. Baş geriye yatırılmamalıdır, çünkü kan boğaza kaçabilir.',
        'Eğitmen son olarak 112\'yi aradığımızda sakin olmamızı, adresimizi açıkça söylememizi ve görevli “kapatabilirsin” diyene kadar telefonu kapatmamamızı istedi.'],
      sorular: [['Eğitmene göre ilk yardımın en önemli kuralı nedir?', 'Telaşa kapılmamak ve önce güvenliği sağlamak', ['Hemen hastaneye koşmak', 'Yaraya buz koymak', 'Kimseye haber vermemek']],
        ['Yanıkta ne yapılmalıdır?', 'Yanan bölge akan soğuk suyun altında tutulmalıdır.', ['Yanığa diş macunu sürülmelidir.', 'Yanığa buz konmalıdır.', 'Yanığa yoğurt sürülmelidir.']],
        ['Burun kanamasında baş neden geriye yatırılmamalıdır?', 'Kan boğaza kaçabileceği için', ['Boyun ağrıyacağı için', 'Kanama hızlanacağı için', 'Göz kararacağı için']],
        ['112\'yi arayan kişi hangisini yapmamalıdır?', 'Görevli söylemeden telefonu kapatmak', ['Sakin konuşmak', 'Adresini açıkça söylemek', 'Görevliyi dinlemek']],
        ['Metin hangi amaçla yazılmıştır?', 'İlk yardım kurallarını öğretmek', ['Bir hastaneyi tanıtmak', 'Bir hikâye anlatmak', 'Bir doktorun hayatını anlatmak']]],
      sozcuk: ['telaş', ['acele ve heyecandan kaynaklanan şaşkınlık', 'sakinlik', 'neşe', 'uykusuzluk']],
      sira: ['Telaşa kapılmamak', 'Kendi güvenliğini sağlamak', 'Bir büyüğe haber vermek ya da 112\'yi aramak', 'Görevlinin söylediklerini yapmak'] }),
    'hafta-35': W(35, 8, 'Centilmenlik', 'Sağlık ve spor · Fair play, takım ruhu', { baslik: 'Kazanmaktan Güzel',
      metin: ['Okullar arası futbol turnuvasının finalindeydik. Maçın bitmesine bir dakika kala skor eşitti. Rakip takımın oyuncusu Arda topla bize doğru koşarken birden yere yığıldı. Ayağı burkulmuştu.',
        'Top bizim oyuncumuz Emir\'in ayağına geldi. Kale bomboştu. Emir isteseydi kolayca gol atabilirdi. Ama topu taça attı ve Arda\'nın yanına koştu.',
        'Hakem oyunu durdurdu. Arda\'nın ayağına buz kondu ve oyuncu değişikliği yapıldı. Maç berabere bitti, penaltılarda biz kaybettik.',
        'Tören sırasında hakem mikrofonu aldı: “Bugün kupayı bir takım kazandı ama en büyük ödülü Emir hak etti.” Turnuvanın centilmenlik ödülü Emir\'e verildi. Arda topallayarak gelip Emir\'e sarıldı. O an kaybettiğimizi unuttuk.'],
      sorular: [['Emir topu neden taça atmıştır?', 'Rakip oyuncu sakatlandığı için', ['Gol atmaktan korktuğu için', 'Top patladığı için', 'Hakem öyle istediği için']],
        ['Maçın sonucu nedir?', 'Penaltılarda kaybettiler.', ['Emir\'in golüyle kazandılar.', 'Maç iptal edildi.', 'Hükmen kazandılar.']],
        ['Emir\'in davranışı hangi değere örnektir?', 'Centilmenlik', ['Kıskançlık', 'Bencillik', 'Kurnazlık']],
        ['“O an kaybettiğimizi unuttuk.” cümlesinden hangi sonuç çıkarılır?', 'Dostluk ve saygı, kazanmaktan daha değerli gelmiştir.', ['Takım maçı unutmuştur.', 'Kupa onlara verilmiştir.', 'Maç tekrar oynanacaktır.']],
        ['Metne en uygun başlık hangisidir?', 'Kazanmaktan Güzel', ['Penaltı Atışları', 'Buzun Faydaları', 'Futbol Kuralları']]],
      sozcuk: ['centilmenlik', ['kurallara ve rakibe saygıyla davranma', 'çok hızlı koşma', 'gol atma', 'kupa kazanma']],
      sira: ['Final maçı başladı.', 'Arda\'nın ayağı burkuldu.', 'Emir topu taça attı.', 'Penaltılarda kaybettiler.', 'Emir centilmenlik ödülü aldı.'] }),
    'hafta-36': W(36, 8, 'Doğa Yürüyüşü', 'Sağlık ve spor · Yönerge, yaz tatili', { baslik: 'Haydi Doğa Yürüyüşüne!',
      metin: ['Yaz tatili geldi! Bu tatilde ailenle doğa yürüyüşüne çıkmaya ne dersin? Doğa yürüyüşü hem bedenini güçlendirir hem de zihnini dinlendirir.',
        'Yürüyüşe çıkmadan önce bir plan yap. Rotayı bir büyüğünle birlikte belirle ve hava durumunu kontrol et. Rahat ayakkabılar giy, şapkanı ve güneş kremini unutma.',
        'Çantana mutlaka su, sağlıklı atıştırmalıklar, küçük bir ilk yardım çantası ve bir çöp torbası koy. Yolda yorulursan dinlen; doğa bir yarış alanı değil, keşif alanıdır.',
        'Doğada bulduğun hiçbir şeyi koparma, hayvanları rahatsız etme ve çöplerini mutlaka geri getir. Unutma, doğadan yalnızca fotoğraf al, geride yalnızca ayak izi bırak.'],
      sorular: [['Hangisi yürüyüşten önce yapılması gerekenlerden biri değildir?', 'Çiçek toplamak için poşet almak', ['Rotayı belirlemek', 'Hava durumunu kontrol etmek', 'Rahat ayakkabı giymek']],
        ['Çantaya çöp torbası konmasının amacı nedir?', 'Çöpleri geri getirmek', ['Taş toplamak', 'Yağmurdan korunmak', 'Çiçek koparmak']],
        ['“Doğa bir yarış alanı değil, keşif alanıdır.” cümlesiyle anlatılmak istenen nedir?', 'Acele etmeden doğayı tanımalıyız.', ['Doğada koşmak yasaktır.', 'Yarışlar doğada yapılmalıdır.', 'Doğa çok tehlikelidir.']],
        ['Son paragraftaki “Geride yalnızca ayak izi bırak.” sözünün anlamı nedir?', 'Doğayı bulduğun gibi bırak.', ['Ayakkabılarını çıkar.', 'Yolu işaretle.', 'Çok hızlı yürü.']],
        ['Metin kime seslenmektedir?', 'Okura (sen)', ['Bir ormancıya', 'Bir öğretmene', 'Hayvanlara']]],
      sozcuk: ['rota', ['izlenecek yol', 'yürüyüş ayakkabısı', 'yağmurluk', 'harita kalemi']],
      sira: ['Yürüyüşü planlamak', 'Hava durumuna bakmak', 'Çantayı hazırlamak', 'Yürüyüşe çıkmak', 'Çöpleri geri getirmek'] }),
  };
  const CSS = `.t4-metin{font-size:3.95mm;line-height:1.45}.t4-metin>b{display:block;text-align:center;font-size:4.6mm;margin-bottom:1mm;color:#1d4e89;font-weight:400}.t4-metin p{margin:0 0 1.2mm;text-indent:4mm}`;
  return { T4, CSS };
};
